```javascript
import http from 'k6/http';
import { check } from 'k6';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '120s',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

function parseCsrf(html) {
  // Find input[name=csrf] value, tolerant of attribute order/quoting.
  const re = /<input\b[^>]*\bname\s*=\s*["']?csrf["']?[^>]*>/i;
  const m = html.match(re);
  if (!m) return null;
  const tag = m[0];
  const vm = tag.match(/\bvalue\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
  if (!vm) return null;
  return vm[2] !== undefined ? vm[2] : (vm[3] !== undefined ? vm[3] : vm[4]);
}

function getCookie(jar, name) {
  const cookies = jar.cookiesForURL(BASE);
  const arr = cookies[name];
  return arr && arr.length ? arr[0] : null;
}

function loginFlow() {
  const jar = http.cookieJar();

  // 1. GET login form
  const formRes = http.get(`${BASE}/v2/login-form`, { redirects: 0 });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const csrf = parseCsrf(formRes.body);
  check(csrf, { 'csrf extracted': (v) => !!v });
  if (!csrf) return null;

  // 2. POST login
  const loginRes = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username: 'bench-1', password: 'bench', csrf }),
    { headers: { 'Content-Type': 'application/json' }, redirects: 0 }
  );

  let sessionCsrf = csrf;
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'];
    if (loc) {
      const followRes = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { redirects: 0 });
      check(followRes, { 'login redirect ok': (r) => r.status === 200 });
    }
  } else {
    check(loginRes, { 'login 200': (r) => r.status === 200 });
    try {
      const body = JSON.parse(loginRes.body);
      if (body.csrf) sessionCsrf = body.csrf;
    } catch (e) {}
  }

  return { jar, csrf: sessionCsrf };
}

function authHeaders(csrf, extra) {
  return Object.assign({ 'X-CSRF-Token': csrf, 'Content-Type': 'application/json' }, extra || {});
}

function handleExpiry(res, ctx, retryFn) {
  if (res.status !== 401) return res;
  let err = null;
  try { err = JSON.parse(res.body).error; } catch (e) {}
  if (err === 'expired') {
    const renew = http.post(`${BASE}/v2/session/renew`, '{}', {
      headers: authHeaders(ctx.csrf),
    });
    if (renew.status === 200) {
      try {
        const b = JSON.parse(renew.body);
        if (b.csrf) ctx.csrf = b.csrf;
      } catch (e) {}
    }
    if (ctx.cartId) {
      http.post(`${BASE}/v2/carts/${ctx.cartId}/recover`, '{}', {
        headers: authHeaders(ctx.csrf),
      });
    }
    return retryFn();
  }
  return res;
}

function pickProduct(catalogBody) {
  try {
    const data = JSON.parse(catalogBody);
    const products = data.data.products;
    for (const p of products) {
      for (const v of p.variants) {
        if (v.in_stock) return { product_id: p.id, variant_id: v.id };
      }
    }
  } catch (e) {}
  return null;
}

function traverseCatalog() {
  // Try /v2/catalog first
  let res = http.get(`${BASE}/v2/catalog`);
  if (res.status === 200) {
    const p = pickProduct(res.body);
    if (p) return p;
  }
  // Fallback: paginate /v2/catalog/page up to 3 pages
  let url = `${BASE}/v2/catalog/page`;
  for (let i = 0; i < 3 && url; i++) {
    const r = http.get(url);
    if (r.status !== 200) break;
    let body;
    try { body = JSON.parse(r.body); } catch (e) { break; }
    const prod = body.product || (body.data && body.data.product);
    if (prod && prod.variants) {
      for (const v of prod.variants) {
        if (v.in_stock) return { product_id: prod.id, variant_id: v.id };
      }
    }
    const next = body.next;
    if (!next) break;
    url = next.startsWith('http') ? next : `${BASE}${next}`;
  }
  return null;
}

function getChallengeGrant(ctx) {
  const formRes = http.get(`${BASE}/v2/challenge-form`);
  if (formRes.status !== 200) return null;
  const actionM = formRes.body.match(/action\s*=\s*["']([^"']+)["']/i);
  const chalM = formRes.body.match(/<input\b[^>]*\bname\s*=\s*["']?challenge["']?[^>]*>/i);
  if (!actionM || !chalM) return null;
  const action = actionM[1];
  const vm = chalM[0].match(/\bvalue\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
  const challenge = vm ? (vm[2] !== undefined ? vm[2] : (vm[3] !== undefined ? vm[3] : vm[4])) : null;
  if (!challenge) return null;

  const actionUrl = action.startsWith('http') ? action : `${BASE}${action}`;
  const postRes = http.post(actionUrl, JSON.stringify({ challenge }), {
    headers: authHeaders(ctx.csrf),
    redirects: 0,
  });
  if (postRes.status !== 302) return null;
  const loc = postRes.headers['Location'];
  if (!loc) return null;
  const locUrl = loc.startsWith('http') ? loc : `${BASE}${loc}`;
  const getRes = http.get(locUrl, { redirects: 0 });
  if (getRes.status !== 200) return null;
  try {
    const b = JSON.parse(getRes.body);
    if (b.csrf) ctx.csrf = b.csrf;
    return b.grant_id || null;
  } catch (e) {
    return null;
  }
}

function createCart(ctx, product) {
  const payload = { product_id: product.product_id, variant_id: product.variant_id };
  if (ctx.grantId) payload.grant_id = ctx.grantId;

  let res = http.post(`${BASE}/v2/carts`, JSON.stringify(payload), {
    headers: authHeaders(ctx.csrf),
  });
  res = handleExpiry(res, ctx, () =>
    http.post(`${BASE}/v2/carts`, JSON.stringify(payload), { headers: authHeaders(ctx.csrf) })
  );
  check(res, { 'cart created 201': (r) => r.status === 201 });
  if (res.status !== 201) return null;
  let body;
  try { body = JSON.parse(res.body); } catch (e) { return null; }
  if (body.csrf) ctx.csrf = body.csrf;
  ctx.cartId = body.id;
  ctx.cartEtag = res.headers['Etag'] || res.headers['ETag'];
  return body.id;
}

function patchCart(ctx) {
  const payload = JSON.stringify({ quantity: 1 });
  const doPatch = () => {
    const headers = authHeaders(ctx.csrf);
    if (ctx.cartEtag) headers['If-Match'] = ctx.cartEtag;
    return http.patch(`${BASE}/v2/carts/${ctx.cartId}`, payload, { headers });
  };
  let res = doPatch();
  if (res.status === 412) {
    const r = http.get(`${BASE}/v2/carts/${ctx.cartId}`);
    ctx.cartEtag = r.headers['Etag'] || r.headers['ETag'];
    res = doPatch();
  }
  res = handleExpiry(res, ctx, doPatch);
  check(res, { 'cart patched': (r) => r.status === 200 || r.status === 204 });
  try {
    const b = JSON.parse(res.body);
    if (b && b.csrf) ctx.csrf = b.csrf;
  } catch (e) {}
  const et = res.headers['Etag'] || res.headers['ETag'];
  if (et) ctx.cartEtag = et;
}

function reserve(ctx) {
  const doRes = () =>
    http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: ctx.cartId }), {
      headers: authHeaders(ctx.csrf),
    });
  let res = doRes();
  res = handleExpiry(res, ctx, doRes);
  check(res, { 'reservation 202': (r) => r.status === 202 });
  if (res.status !== 202) return null;
  let body;
  try { body = JSON.parse(res.body); } catch (e) { return null; }
  if (body.csrf) ctx.csrf = body.csrf;
  const statusUrl = body.status_url;
  if (!statusUrl) return null;

  for (let i = 0; i < 5; i++) {
    const pollUrl = statusUrl.startsWith('http') ? statusUrl : `${BASE}${statusUrl}`;
    const pr = http.get(pollUrl);
    if (pr.status === 200) {
      try {
        const pb = JSON.parse(pr.body);
        if (pb.csrf) ctx.csrf = pb.csrf;
        if (pb.status === 'ready' && pb.reservation_id) return pb.reservation_id;
        if (pb.status === 'failed') return null;
      } catch (e) {}
    }
    // sleep at least 50ms
    const start = Date.now();
    while (Date.now() - start < 60) { /* busy wait */ }
  }
  return null;
}

function placeOrder(ctx, reservationId) {
  const idemKey = `cart-${ctx.cartId}-${__VU}-${__ITER}`;
  const payload = { cart_id: ctx.cartId };
  if (reservationId) payload.reservation_id = reservationId;

  const doOrder = () => {
    const headers = authHeaders(ctx.csrf, { 'Idempotency-Key': idemKey });
    if (ctx.cartEtag) headers['If-Match'] = ctx.cartEtag;
    return http.post(`${BASE}/v2/orders`, JSON.stringify(payload), { headers });
  };
  let res = doOrder();
  res = handleExpiry(res, ctx, doOrder);
  check(res, { 'order 201 accepted': (r) => {
    if (r.status !== 201) return false;
    try { return JSON.parse(r.body).accepted === true; } catch (e) { return false; }
  }});
  try {
    const b = JSON.parse(res.body);
    if (b && b.csrf) ctx.csrf = b.csrf;
  } catch (e) {}
}

export default function () {
  const ctx = loginFlow();
  if (!ctx) return;

  const product = traverseCatalog();
  check(product, { 'product found': (v) => !!v });
  if (!product) return;

  ctx.grantId = getChallengeGrant(ctx);

  const cartId = createCart(ctx, product);
  if (!cartId) return;

  patchCart(ctx);

  const reservationId = reserve(ctx);
  check(reservationId, { 'reservation ready': (v) => !!v });
  if (!reservationId) return;

  placeOrder(ctx, reservationId);
}
