```javascript
import http from 'k6/http';
import { check } from 'k6';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

function parseCsrf(html) {
  // Find all input tags, then pick the one whose name attribute is csrf,
  // regardless of attribute ordering or decoys.
  const inputs = html.match(/<input\b[^>]*>/gi) || [];
  for (const tag of inputs) {
    const nameMatch = tag.match(/\bname\s*=\s*["']?([^"'\s>]+)["']?/i);
    if (!nameMatch) continue;
    if (nameMatch[1] !== 'csrf') continue;
    const valMatch = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (valMatch) return valMatch[1];
  }
  return null;
}

function getCsrfFromJson(body) {
  try {
    const j = JSON.parse(body);
    return j && j.csrf ? j.csrf : null;
  } catch (e) {
    return null;
  }
}

function authHeaders(csrf, extra) {
  const h = { 'Content-Type': 'application/json' };
  if (csrf) h['X-CSRF-Token'] = csrf;
  if (extra) for (const k in extra) h[k] = extra[k];
  return h;
}

function login(user) {
  const formRes = http.get(`${BASE}/v2/login-form`, { redirects: 0 });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const csrf = parseCsrf(formRes.body);
  check(csrf, { 'csrf extracted': (v) => !!v });
  if (!csrf) return null;

  const loginRes = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username: user, password: 'bench', csrf }),
    { headers: authHeaders(csrf), redirects: 0 }
  );

  let token = null;
  let ok = false;
  if (loginRes.status === 200) {
    token = getCsrfFromJson(loginRes.body);
    ok = true;
  } else if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'] || loginRes.headers['location'];
    if (loc) {
      const followRes = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, {
        redirects: 0,
      });
      if (followRes.status === 200) {
        token = getCsrfFromJson(followRes.body);
        ok = true;
      }
    }
  }
  check(ok && token, { 'login authorized': (v) => !!v });
  return token;
}

function collectProducts() {
  const products = [];
  const seen = new Set();
  const first = http.get(`${BASE}/v2/catalog`, { redirects: 0 });
  check(first, { 'catalog 200': (r) => r.status === 200 });
  try {
    const j = JSON.parse(first.body);
    const list = (j.data && j.data.products) || [];
    for (const p of list) {
      if (!seen.has(p.id)) {
        seen.add(p.id);
        products.push(p);
      }
    }
  } catch (e) {}

  let next = null;
  try {
    const j = JSON.parse(first.body);
    next = j.next;
  } catch (e) {}

  let pages = 0;
  while (next && pages < 3) {
    pages++;
    const url = next.startsWith('http') ? next : `${BASE}${next}`;
    const res = http.get(url, { redirects: 0 });
    if (res.status !== 200) break;
    try {
      const j = JSON.parse(res.body);
      const list = (j.data && j.data.products) || [];
      for (const p of list) {
        if (!seen.has(p.id)) {
          seen.add(p.id);
          products.push(p);
        }
      }
      next = j.next;
    } catch (e) {
      break;
    }
  }
  return products;
}

function pickVariant(product) {
  if (!product || !product.variants) return null;
  for (const v of product.variants) {
    if (v.in_stock) return v;
  }
  return product.variants[0] || null;
}

function solveChallenge(csrf) {
  const formRes = http.get(`${BASE}/v2/challenge-form`, { redirects: 0 });
  if (formRes.status !== 200) return null;
  const actionMatch = formRes.body.match(/action\s*=\s*["']([^"']+)["']/i);
  const challengeMatch = formRes.body.match(
    /<input\b[^>]*\bname\s*=\s*["']?challenge["']?[^>]*>/i
  );
  if (!actionMatch || !challengeMatch) return null;
  let challengeVal = null;
  const valMatch = challengeMatch[0].match(/\bvalue\s*=\s*["']([^"']*)["']/i);
  if (valMatch) challengeVal = valMatch[1];
  if (!challengeVal) return null;

  const action = actionMatch[1];
  const actionUrl = action.startsWith('http') ? action : `${BASE}${action}`;
  const postRes = http.post(
    actionUrl,
    JSON.stringify({ challenge: challengeVal }),
    { headers: authHeaders(csrf), redirects: 0 }
  );
  if (postRes.status !== 302) return null;
  const loc = postRes.headers['Location'] || postRes.headers['location'];
  if (!loc) return null;
  const locUrl = loc.startsWith('http') ? loc : `${BASE}${loc}`;
  const finalRes = http.get(locUrl, { redirects: 0 });
  if (finalRes.status !== 200) return null;
  try {
    const j = JSON.parse(finalRes.body);
    return j.grant_id || null;
  } catch (e) {
    return null;
  }
}

function createCart(csrf, product, variant, grantId) {
  const payload = { product_id: product.id, variant_id: variant.id };
  if (grantId) payload.grant_id = grantId;
  const res = http.post(`${BASE}/v2/carts`, JSON.stringify(payload), {
    headers: authHeaders(csrf),
    redirects: 0,
  });
  check(res, { 'cart created 201': (r) => r.status === 201 });
  if (res.status !== 201) return null;
  let cartId = null;
  let newCsrf = csrf;
  try {
    const j = JSON.parse(res.body);
    cartId = j.id;
    if (j.csrf) newCsrf = j.csrf;
  } catch (e) {}
  const etag = res.headers['Etag'] || res.headers['ETag'] || res.headers['etag'];
  return { cartId, csrf: newCsrf, etag };
}

function patchCart(csrf, cartId, etag, quantity) {
  const url = `${BASE}/v2/carts/${cartId}`;
  const payload = JSON.stringify({ quantity });
  let res = http.patch(url, payload, {
    headers: authHeaders(csrf, { 'If-Match': etag || '' }),
    redirects: 0,
  });
  if (res.status === 412) {
    const reread = http.get(url, { redirects: 0 });
    const newEtag =
      reread.headers['Etag'] || reread.headers['ETag'] || reread.headers['etag'];
    res = http.patch(url, payload, {
      headers: authHeaders(csrf, { 'If-Match': newEtag || '' }),
      redirects: 0,
    });
  }
  check(res, { 'cart patched': (r) => r.status === 200 || r.status === 204 });
  let newCsrf = csrf;
  try {
    const j = JSON.parse(res.body);
    if (j && j.csrf) newCsrf = j.csrf;
  } catch (e) {}
  return { ok: res.status === 200 || res.status === 204, csrf: newCsrf };
}

function reserve(csrf, cartId) {
  const res = http.post(
    `${BASE}/v2/reservations`,
    JSON.stringify({ cart_id: cartId }),
    { headers: authHeaders(csrf), redirects: 0 }
  );
  check(res, { 'reservation 202': (r) => r.status === 202 });
  if (res.status !== 202) return null;
  let statusUrl = null;
  let newCsrf = csrf;
  try {
    const j = JSON.parse(res.body);
    statusUrl = j.status_url;
    if (j.csrf) newCsrf = j.csrf;
  } catch (e) {}
  if (!statusUrl) return null;
  const url = statusUrl.startsWith('http') ? statusUrl : `${BASE}${statusUrl}`;
  for (let i = 0; i < 5; i++) {
    if (i > 0) {
      // sleep at least 50ms
      const start = Date.now();
      while (Date.now() - start < 60) {}
    }
    const poll = http.get(url, { redirects: 0 });
    if (poll.status !== 200) continue;
    try {
      const j = JSON.parse(poll.body);
      if (j.csrf) newCsrf = j.csrf;
      if (j.status === 'ready' && j.reservation_id) {
        return { reservationId: j.reservation_id, csrf: newCsrf };
      }
      if (j.status === 'failed') return null;
    } catch (e) {}
  }
  return null;
}

function placeOrder(csrf, cartId, reservationId, etag) {
  const idem = `idem-${cartId}-${__VU}-${__ITER}`;
  const headers = authHeaders(csrf, { 'Idempotency-Key': idem });
  if (etag) headers['If-Match'] = etag;
  const payload = { cart_id: cartId };
  if (reservationId) payload.reservation_id = reservationId;
  const res = http.post(`${BASE}/v2/orders`, JSON.stringify(payload), {
    headers,
    redirects: 0,
  });
  let ok = false;
  try {
    const j = JSON.parse(res.body);
    ok = res.status === 201 && j.accepted === true;
  } catch (e) {}
  check(res, { 'order accepted': () => ok });
  return ok;
}

export default function () {
  const user = `bench-${__VU}`;
  const csrf0 = login(user);
  if (!csrf0) return;

  const products = collectProducts();
  if (!products.length) return;
  const product = products[0];
  const variant = pickVariant(product);
  if (!variant) return;

  const grantId = solveChallenge(csrf0);
  const cart = createCart(csrf0, product, variant, grantId);
  if (!cart || !cart.cartId) return;

  const patched = patchCart(cart.csrf, cart.cartId, cart.etag, 1);
  if (!patched.ok) return;

  const reservation = reserve(patched.csrf, cart.cartId);
  if (!reservation) return;

  placeOrder(reservation.csrf, cart.cartId, reservation.reservationId, cart.etag);
}
