import http from 'k6/http';
import { check } from 'k6';

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '120s',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

function parseCsrf(html) {
  // input[name=csrf] with possible attribute variants / decoys
  const re = /<input\b[^>]*\bname\s*=\s*["']?csrf["']?[^>]*>/i;
  const m = html.match(re);
  if (!m) return null;
  const tag = m[0];
  const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
  return vm ? vm[1] : null;
}

function extractLocation(res) {
  const h = res.headers['Location'] || res.headers['location'];
  if (!h) return null;
  if (h.startsWith('http')) return h;
  return BASE + h;
}

function getCsrfFromJson(res) {
  try {
    const b = JSON.parse(res.body);
    return b && b.csrf ? b.csrf : null;
  } catch (e) {
    return null;
  }
}

function login(jar) {
  const formRes = http.get(`${BASE}/v2/login-form`, { jar, redirects: 0 });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const csrf = parseCsrf(formRes.body);
  check(csrf, { 'login csrf found': (c) => !!c });

  const loginRes = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username: 'bench-1', password: 'bench', csrf }),
    { jar, redirects: 0, headers: { 'Content-Type': 'application/json' } }
  );

  if (loginRes.status === 302) {
    const loc = extractLocation(loginRes);
    check(loc, { 'login redirect location': (l) => !!l });
    const followRes = http.get(loc, { jar, redirects: 0 });
    check(followRes, { 'login follow 200': (r) => r.status === 200 });
    const c2 = getCsrfFromJson(followRes);
    if (c2) return c2;
  }

  const c = getCsrfFromJson(loginRes);
  check(c, { 'login csrf returned': (x) => !!x });
  return c;
}

function findInStockProduct(catalogBody) {
  let data;
  try {
    data = JSON.parse(catalogBody);
  } catch (e) {
    return null;
  }
  const products = (data && data.data && data.data.products) || [];
  for (const p of products) {
    const variants = p.variants || [];
    for (const v of variants) {
      if (v.in_stock) {
        return { product_id: p.id, variant_id: v.id };
      }
    }
  }
  return null;
}

function traverseCatalog(jar) {
  // First try /v2/catalog
  const res = http.get(`${BASE}/v2/catalog`, { jar, redirects: 0 });
  check(res, { 'catalog 200': (r) => r.status === 200 });
  let found = findInStockProduct(res.body);
  if (found) return found;

  // Fall back to paged traversal, at most 3 pages
  let url = `${BASE}/v2/catalog/page`;
  for (let i = 0; i < 3; i++) {
    const r = http.get(url, { jar, redirects: 0 });
    check(r, { 'catalog page 200': (x) => x.status === 200 });
    let body;
    try {
      body = JSON.parse(r.body);
    } catch (e) {
      return null;
    }
    // page returns one product plus next
    const prod = body.product || (body.data && body.data.product);
    if (prod) {
      const variants = prod.variants || [];
      for (const v of variants) {
        if (v.in_stock) {
          return { product_id: prod.id, variant_id: v.id };
        }
      }
    }
    const next = body.next;
    if (!next) break;
    url = next.startsWith('http') ? next : BASE + next;
  }
  return null;
}

function createCart(jar, csrf, product_id, variant_id, grant_id) {
  const payload = { product_id, variant_id };
  if (grant_id) payload.grant_id = grant_id;
  const res = http.post(`${BASE}/v2/carts`, JSON.stringify(payload), {
    jar,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  check(res, { 'cart created 201': (r) => r.status === 201 });
  let body = {};
  try {
    body = JSON.parse(res.body);
  } catch (e) {}
  const newCsrf = body.csrf || csrf;
  return { id: body.id, csrf: newCsrf, etag: res.headers['Etag'] || res.headers['etag'] };
}

function patchQuantity(jar, csrf, cartId, etag, qty) {
  const res = http.patch(`${BASE}/v2/carts/${cartId}`, JSON.stringify({ quantity: qty }), {
    jar,
    redirects: 0,
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag || '',
    },
  });
  if (res.status === 412) {
    const re = http.get(`${BASE}/v2/carts/${cartId}`, { jar, redirects: 0 });
    const newEtag = re.headers['Etag'] || re.headers['etag'];
    const retry = http.patch(`${BASE}/v2/carts/${cartId}`, JSON.stringify({ quantity: qty }), {
      jar,
      redirects: 0,
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
        'If-Match': newEtag || '',
      },
    });
    return { res: retry, etag: newEtag };
  }
  return { res, etag };
}

function placeOrder(jar, csrf, cartId, etag, idemKey) {
  const res = http.post(`${BASE}/v2/orders`, JSON.stringify({ cart_id: cartId }), {
    jar,
    redirects: 0,
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'Idempotency-Key': idemKey,
      'If-Match': etag || '',
    },
  });
  return res;
}

export default function () {
  const jar = http.cookieJar();
  const csrf = login(jar);
  check(csrf, { 'have csrf': (c) => !!c });

  const sel = traverseCatalog(jar);
  check(sel, { 'found in-stock product': (s) => !!s });
  if (!sel) return;

  const cart = createCart(jar, csrf, sel.product_id, sel.variant_id, null);
  check(cart.id, { 'cart id present': (c) => !!c });
  if (!cart.id) return;

  const patched = patchQuantity(jar, cart.csrf, cart.id, cart.etag, 1);
  check(patched.res, { 'patch ok': (r) => r.status === 200 || r.status === 204 });

  const idemKey = `order-${cart.id}-${__VU}-${__ITER}`;
  const orderRes = placeOrder(jar, cart.csrf, cart.id, patched.etag, idemKey);
  check(orderRes, {
    'order 201': (r) => r.status === 201,
    'order accepted true': (r) => {
      try {
        return JSON.parse(r.body).accepted === true;
      } catch (e) {
        return false;
      }
    },
  });
}
