import http from 'k6/http';
import { check } from 'k6';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    journey: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '120s',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

function jar() {
  return http.cookieJar();
}

function parseCsrfFromForm(body) {
  // input[name=csrf] with possible attribute variants / decoys
  const re = /<input\b[^>]*\bname\s*=\s*["']?csrf["']?[^>]*>/i;
  const m = body.match(re);
  if (!m) return null;
  const tag = m[0];
  const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
  return vm ? vm[1] : null;
}

function getJson(res) {
  try { return res.json(); } catch (e) { return null; }
}

function login(jarRef, username) {
  const formRes = http.get(`${BASE}/v2/login-form`, { jar: jarRef, redirects: 0 });
  const csrf = parseCsrfFromForm(formRes.body || '');
  if (!csrf) return null;
  const loginRes = http.post(`${BASE}/v2/login`, JSON.stringify({
    username, password: 'bench', csrf,
  }), {
    jar: jarRef,
    redirects: 0,
    headers: { 'Content-Type': 'application/json' },
  });
  let token = csrf;
  let user = null;
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'] || loginRes.headers['location'];
    if (loc) {
      const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar: jarRef, redirects: 0 });
      const j = getJson(follow);
      if (j && j.csrf) token = j.csrf;
      if (j && j.user) user = j.user;
    }
  } else {
    const j = getJson(loginRes);
    if (j && j.csrf) token = j.csrf;
    if (j && j.user) user = j.user;
  }
  return { csrf: token, user };
}

function findEligibleProduct(jarRef) {
  // First try catalog root
  const rootRes = http.get(`${BASE}/v2/catalog`, { jar: jarRef, redirects: 0 });
  const root = getJson(rootRes);
  if (root && root.data && Array.isArray(root.data.products)) {
    for (const p of root.data.products) {
      if (!p || !Array.isArray(p.variants)) continue;
      for (const v of p.variants) {
        if (v && v.in_stock) return { product_id: p.id, variant_id: v.id };
      }
    }
  }
  // Paginate via /v2/catalog/page
  let next = `${BASE}/v2/catalog/page`;
  let pages = 0;
  while (next && pages < 3) {
    const res = http.get(next.startsWith('http') ? next : `${BASE}${next}`, { jar: jarRef, redirects: 0 });
    const j = getJson(res);
    if (!j) break;
    const p = j.product || (j.data && j.data.product);
    if (p && Array.isArray(p.variants)) {
      for (const v of p.variants) {
        if (v && v.in_stock) return { product_id: p.id, variant_id: v.id };
      }
    }
    const n = j.next;
    if (!n) break;
    next = n.startsWith('http') ? n : `${BASE}${n}`;
    pages++;
  }
  return null;
}

function solveChallenge(jarRef, csrf) {
  const formRes = http.get(`${BASE}/v2/challenge-form`, { jar: jarRef, redirects: 0 });
  const body = formRes.body || '';
  const actionM = body.match(/<form\b[^>]*\baction\s*=\s*["']([^"']+)["']/i);
  const chalM = body.match(/<input\b[^>]*\bname\s*=\s*["']?challenge["']?[^>]*>/i);
  if (!actionM || !chalM) return null;
  const action = actionM[1];
  const vm = chalM[0].match(/\bvalue\s*=\s*["']([^"']*)["']/i);
  const challenge = vm ? vm[1] : '';
  const postRes = http.post(action.startsWith('http') ? action : `${BASE}${action}`,
    JSON.stringify({ challenge }), {
      jar: jarRef,
      redirects: 0,
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    });
  let loc = postRes.headers['Location'] || postRes.headers['location'];
  if (!loc) return null;
  const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar: jarRef, redirects: 0 });
  const j = getJson(follow);
  if (!j) return null;
  return { grant_id: j.grant_id, csrf: j.csrf || csrf };
}

function createCart(jarRef, csrf, product_id, variant_id, grant_id) {
  const payload = { product_id, variant_id };
  if (grant_id) payload.grant_id = grant_id;
  const res = http.post(`${BASE}/v2/carts`, JSON.stringify(payload), {
    jar: jarRef,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  const j = getJson(res);
  if (!j || !j.id) return null;
  return { id: j.id, csrf: j.csrf || csrf, etag: res.headers['Etag'] || res.headers['ETag'] || res.headers['etag'] };
}

function patchQuantity(jarRef, csrf, cartId, etag, qty) {
  const payload = JSON.stringify({ quantity: qty });
  let res = http.patch(`${BASE}/v2/carts/${cartId}`, payload, {
    jar: jarRef,
    redirects: 0,
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag || '',
    },
  });
  if (res.status === 412) {
    const re = http.get(`${BASE}/v2/carts/${cartId}`, { jar: jarRef, redirects: 0 });
    const newEtag = re.headers['Etag'] || re.headers['ETag'] || re.headers['etag'];
    res = http.patch(`${BASE}/v2/carts/${cartId}`, payload, {
      jar: jarRef,
      redirects: 0,
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
        'If-Match': newEtag || '',
      },
    });
  }
  const j = getJson(res);
  return { ok: res.status >= 200 && res.status < 300, csrf: (j && j.csrf) || csrf, etag: res.headers['Etag'] || res.headers['ETag'] || res.headers['etag'] };
}

function reserve(jarRef, csrf, cartId) {
  const res = http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    jar: jarRef,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  const j = getJson(res);
  if (!j || !j.status_url) return null;
  let token = j.csrf || csrf;
  let statusUrl = j.status_url;
  for (let i = 0; i < 5; i++) {
    if (i > 0) {
      // bounded wait ~60ms
      const t0 = Date.now();
      while (Date.now() - t0 < 60) { /* spin */ }
    }
    const sres = http.get(statusUrl.startsWith('http') ? statusUrl : `${BASE}${statusUrl}`, {
      jar: jarRef, redirects: 0,
    });
    const sj = getJson(sres);
    if (!sj) return null;
    if (sj.csrf) token = sj.csrf;
    if (sj.status === 'ready' && sj.reservation_id) {
      return { reservation_id: sj.reservation_id, csrf: token };
    }
    if (sj.status === 'failed') return null;
    if (sj.status_url) statusUrl = sj.status_url;
  }
  return null;
}

function placeOrder(jarRef, csrf, cartId, reservationId, etag) {
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': `cart-${cartId}-order`,
  };
  if (etag) headers['If-Match'] = etag;
  const payload = { cart_id: cartId };
  if (reservationId) payload.reservation_id = reservationId;
  const res = http.post(`${BASE}/v2/orders`, JSON.stringify(payload), {
    jar: jarRef, redirects: 0, headers,
  });
  const j = getJson(res);
  return { status: res.status, body: j };
}

export default function () {
  const jarRef = jar();
  const username = `bench-${__VU}`;
  const loginInfo = login(jarRef, username);
  check(loginInfo, { 'login ok': (v) => v && v.csrf });
  if (!loginInfo) return;
  let csrf = loginInfo.csrf;

  const prod = findEligibleProduct(jarRef);
  check(prod, { 'eligible product found': (v) => !!v });
  if (!prod) return;

  // Try challenge to get grant_id (optional but protocol allows)
  let grant = null;
  try {
    grant = solveChallenge(jarRef, csrf);
    if (grant && grant.csrf) csrf = grant.csrf;
  } catch (e) { grant = null; }

  const cart = createCart(jarRef, csrf, prod.product_id, prod.variant_id, grant ? grant.grant_id : null);
  check(cart, { 'cart created': (v) => !!v && !!v.id });
  if (!cart) return;
  csrf = cart.csrf;

  const patched = patchQuantity(jarRef, csrf, cart.id, cart.etag, 1);
  check(patched, { 'cart patched': (v) => v && v.ok });
  csrf = patched.csrf;

  const resv = reserve(jarRef, csrf, cart.id);
  check(resv, { 'reservation ready': (v) => !!v && !!v.reservation_id });
  if (!resv) return;
  csrf = resv.csrf;

  const order = placeOrder(jarRef, csrf, cart.id, resv.reservation_id, patched.etag);
  check(order, {
    'order accepted': (o) => o && o.status === 201 && o.body && o.body.accepted === true && !!o.body.id,
  });
}
