  });

  // Verify exactly one intended mutation: quantity equals requested.
  const verify = http.get(`${BASE}/v2/carts/${cart.id}`, { jar: jarRef, redirects: 0 });
  check(verify, { 'verify cart 200': (r) => r.status === 200 });
  let vbody = {};
  try { vbody = verify.json(); } catch (e) {}
  const items = (vbody && (vbody.items || (vbody.data && vbody.data.items))) || [];
  const match = items.find((it) => it.variant_id === prod.variant_id || it.product_id === prod.product_id);
  check(match, { 'cart line present': (m) => !!m });
  if (match) {
    check(match, { 'quantity preserved': (m) => m.quantity === quantity });
  }
}
