    nextUrl = pg && pg.next ? pg.next : null;
  }
  check(productId, { 'found in-stock product': (v) => !!v });

  // Challenge flow for grant_id
  let grantId = null;
  res = http.get(BASE + '/v2/challenge-form', { redirects: 0 });
  check(res, { 'challenge-form 200': (r) => r.status === 200 });
  const challenge = extractChallenge(res.body);
  const action = extractFormAction(res.body);
  check(challenge, { 'challenge extracted': (v) => !!v });
  check(action, { 'challenge action extracted': (v) => !!v });
  if (challenge && action) {
    const actionUrl = action.startsWith('http') ? action : BASE + action;
    res = http.post(actionUrl, JSON.stringify({ challenge }), {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
      redirects: 0,
    });
    if (res.status === 302) {
      const loc = getHeader(res, 'Location');
      if (loc) {
        const locUrl = loc.startsWith('http') ? loc : BASE + loc;
        res = http.get(locUrl, { redirects: 0 });
        const gb = parseJson(res);
        if (gb) {
          if (gb.grant_id) grantId = gb.grant_id;
          if (gb.csrf) csrf = gb.csrf;
        }
      }
    }
  }

  // Create cart
  const cartPayload = { product_id: productId, variant_id: variantId };
  if (grantId) cartPayload.grant_id = grantId;
  res = http.post(BASE + '/v2/carts', JSON.stringify(cartPayload), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  check(res, { 'cart created 201': (r) => r.status === 201 });
  body = parseJson(res);
  if (body) {
    cartId = body.id;
    if (body.csrf) csrf = body.csrf;
  }
  cartEtag = getHeader(res, 'ETag');
  check(cartId, { 'cart id present': (v) => !!v });

  // PATCH quantity with If-Match, retry once on 412
  if (cartId) {
    const patchPayload = JSON.stringify({ quantity: 1 });
    let attempt = 0;
    let done = false;
    while (attempt < 2 && !done) {
      attempt++;
      const headers = { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf };
      if (cartEtag) headers['If-Match'] = cartEtag;
      res = http.patch(BASE + '/v2/carts/' + cartId, patchPayload, { headers, redirects: 0 });
      if (res.status === 412) {
        // re-read
        const r2 = http.get(BASE + '/v2/carts/' + cartId, { redirects: 0 });
        cartEtag = getHeader(r2, 'ETag');
        continue;
      }
      done = true;
      check(res, { 'patch ok': (r) => r.status === 200 || r.status === 204 });
      const pb = parseJson(res);
      if (pb && pb.csrf) csrf = pb.csrf;
      const ne = getHeader(res, 'ETag');
      if (ne) cartEtag = ne;
    }
  }

  // Reservation
  let reservationId = null;
  if (cartId) {
    res = http.post(BASE + '/v2/reservations', JSON.stringify({ cart_id: cartId }), {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
      redirects: 0,
    });
    check(res, { 'reservation 202': (r) => r.status === 202 });
    body = parseJson(res);
    let statusUrl = body && body.status_url ? body.status_url : null;
    if (body && body.csrf) csrf = body.csrf;
    if (statusUrl) {
      const sUrl = statusUrl.startsWith('http') ? statusUrl : BASE + statusUrl;
      let polls = 0;
      while (polls < 5) {
        polls++;
        sleep(60);
        const pr = http.get(sUrl, { redirects: 0 });
        const pb = parseJson(pr);
        if (pb) {
          if (pb.csrf) csrf = pb.csrf;
          if (pb.status === 'ready' && pb.reservation_id) {
            reservationId = pb.reservation_id;
            break;
          }
          if (pb.status === 'failed') break;
        }
      }
    }
  }

  // Order
  if (cartId) {
    const orderPayload = { cart_id: cartId };
    if (reservationId) orderPayload.reservation_id = reservationId;
    const idemKey = 'idem-' + cartId + '-' + vu + '-' + iter;
    const headers = {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'Idempotency-Key': idemKey,
    };
    if (cartEtag) headers['If-Match'] = cartEtag;
    res = http.post(BASE + '/v2/orders', JSON.stringify(orderPayload), { headers, redirects: 0 });
    check(res, { 'order 201 accepted': (r) => r.status === 201 });
    body = parseJson(res);
    check(body, { 'order accepted true': (b) => b && b.accepted === true });
    if (body && body.csrf) csrf = body.csrf;
  }

  // Business work
  res = http.post(BASE + '/v2/work', JSON.stringify({}), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  let retries = 0;
  while (res.status === 429 && retries < 4) {
    retries++;
    sleep(1000);
    res = http.post(BASE + '/v2/work', JSON.stringify({}), {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
      redirects: 0,
    });
  }
  check(res, { 'work ok': (r) => r.status === 200 });
  body = parseJson(res);
  if (body && body.csrf) csrf = body.csrf;
}
