import http from 'k6/http';
import { check } from 'k6';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    journey: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '120s',
    },
  },
};

function jar() {
  return http.cookieJar();
}

function parseCsrf(html) {
  // input[name=csrf] with possible attribute variants / decoys
  const re = /<input\b[^>]*\bname\s*=\s*["']?csrf["']?[^>]*>/i;
  const m = html.match(re);
  if (!m) return null;
  const tag = m[0];
  const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
  return vm ? vm[1] : null;
}

function getLoginForm(cj) {
  const res = http.get(`${BASE}/v2/login-form`, { jar: cj, redirects: 0 });
  check(res, { 'login-form 200': (r) => r.status === 200 });
  return parseCsrf(res.body || '');
}

function login(cj, user) {
  const csrf = getLoginForm(cj);
  const res = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username: user, password: 'bench', csrf }),
    { jar: cj, redirects: 0, headers: { 'Content-Type': 'application/json' } }
  );
  let body = {};
  try { body = res.json() || {}; } catch (e) {}
  check(res, { 'login ok': (r) => r.status === 200 || r.status === 302 });
  return body.csrf || csrf;
}

function pickProduct(cj) {
  const res = http.get(`${BASE}/v2/catalog`, { jar: cj, redirects: 0 });
  check(res, { 'catalog 200': (r) => r.status === 200 });
  let body = {};
  try { body = res.json() || {}; } catch (e) {}
  const products = (body.data && body.data.products) || [];
  for (const p of products) {
    for (const v of (p.variants || [])) {
      if (v.in_stock) return { product_id: p.id, variant_id: v.id };
    }
  }
  // fallback: page traversal
  let next = '/v2/catalog/page';
  let pages = 0;
  while (next && pages < 3) {
    const r = http.get(`${BASE}${next}`, { jar: cj, redirects: 0 });
    let b = {};
    try { b = r.json() || {}; } catch (e) {}
    const p = b.product || (b.data && b.data.product);
    if (p) {
      for (const v of (p.variants || [])) {
        if (v.in_stock) return { product_id: p.id, variant_id: v.id };
      }
    }
    next = b.next;
    pages++;
  }
  return null;
}

function solveChallenge(cj, csrf) {
  const res = http.get(`${BASE}/v2/challenge-form`, { jar: cj, redirects: 0 });
  const html = res.body || '';
  const actionM = html.match(/<form\b[^>]*\baction\s*=\s*["']([^"']+)["']/i);
  const chalM = html.match(/<input\b[^>]*\bname\s*=\s*["']?challenge["']?[^>]*>/i);
  if (!actionM || !chalM) return { grant_id: null, csrf };
  const action = actionM[1];
  const vm = chalM[0].match(/\bvalue\s*=\s*["']([^"']*)["']/i);
  const challenge = vm ? vm[1] : '';
  const post = http.post(
    action.startsWith('http') ? action : `${BASE}${action}`,
    JSON.stringify({ challenge }),
    { jar: cj, redirects: 0, headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf } }
  );
  let loc = post.headers['Location'] || post.headers['location'];
  if (!loc) return { grant_id: null, csrf };
  const g = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar: cj, redirects: 0 });
  let b = {};
  try { b = g.json() || {}; } catch (e) {}
  return { grant_id: b.grant_id || null, csrf: b.csrf || csrf };
}

function createCart(cj, csrf, prod, grant_id) {
  const payload = { product_id: prod.product_id, variant_id: prod.variant_id };
  if (grant_id) payload.grant_id = grant_id;
  const res = http.post(`${BASE}/v2/carts`, JSON.stringify(payload), {
    jar: cj, redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  let body = {};
  try { body = res.json() || {}; } catch (e) {}
  return { status: res.status, body, etag: res.headers['Etag'] || res.headers['etag'] };
}

function renew(cj, csrf) {
  const res = http.post(`${BASE}/v2/session/renew`, '{}', {
    jar: cj, redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  let body = {};
  try { body = res.json() || {}; } catch (e) {}
  return { status: res.status, csrf: body.csrf || csrf };
}

function recoverCart(cj, csrf, cartId) {
  const res = http.post(`${BASE}/v2/carts/${cartId}/recover`, '{}', {
    jar: cj, redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  let body = {};
  try { body = res.json() || {}; } catch (e) {}
  return { status: res.status, csrf: body.csrf || csrf };
}

function patchQuantity(cj, csrf, cartId, etag, qty) {
  const res = http.patch(`${BASE}/v2/carts/${cartId}`, JSON.stringify({ quantity: qty }), {
    jar: cj, redirects: 0,
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag || '',
    },
  });
  let body = {};
  try { body = res.json() || {}; } catch (e) {}
  return { status: res.status, body, etag: res.headers['Etag'] || res.headers['etag'] };
}

function reserve(cj, csrf, cartId) {
  const res = http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    jar: cj, redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  let body = {};
  try { body = res.json() || {}; } catch (e) {}
  return { status: res.status, body, csrf: body.csrf || csrf };
}

function pollReservation(cj, statusUrl) {
  for (let i = 0; i < 5; i++) {
    const res = http.get(statusUrl.startsWith('http') ? statusUrl : `${BASE}${statusUrl}`, {
      jar: cj, redirects: 0,
    });
    let body = {};
    try { body = res.json() || {}; } catch (e) {}
    if (body.status === 'ready') return body.reservation_id || null;
    if (body.status === 'failed') return null;
    // sleep 60ms
    const t = Date.now(); while (Date.now() - t < 60) {}
  }
  return null;
}

function placeOrder(cj, csrf, cartId, reservationId, idemKey, etag) {
  const payload = { cart_id: cartId };
  if (reservationId) payload.reservation_id = reservationId;
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idemKey,
  };
  if (etag) headers['If-Match'] = etag;
  const res = http.post(`${BASE}/v2/orders`, JSON.stringify(payload), {
    jar: cj, redirects: 0, headers,
  });
  let body = {};
  try { body = res.json() || {}; } catch (e) {}
  return { status: res.status, body, csrf: body.csrf || csrf };
}

function isExpired(res) {
  if (res.status !== 401) return false;
  try {
    const b = res.json() || {};
    return b.error === 'expired' || b.error === 'session';
  } catch (e) { return false; }
}

export default function () {
  const user = `bench-${__VU}`;
  const cj = jar();
  let csrf = login(cj, user);

  // Fresh cart
  const prod = pickProduct(cj);
  check(prod, { 'product found': (p) => p !== null });
  if (!prod) return;

  let grant_id = null;
  // Try challenge path (may or may not be required)
  const chal = solveChallenge(cj, csrf);
  if (chal.csrf) csrf = chal.csrf;
  if (chal.grant_id) grant_id = chal.grant_id;

  let cart = createCart(cj, csrf, prod, grant_id);
  if (cart.status === 401 && isExpired({ status: 401, json: () => cart.body })) {
    // renew and retry once
    const r = renew(cj, csrf);
    csrf = r.csrf;
    cart = createCart(cj, csrf, prod, grant_id);
  }
  check(cart, { 'cart created': (c) => c.status === 201 && c.body.id });
  if (cart.status !== 201 || !cart.body.id) return;
  const cartId = cart.body.id;
  if (cart.body.csrf) csrf = cart.body.csrf;
  let etag = cart.etag;

  // PATCH quantity with 412 retry
  let patched = patchQuantity(cj, csrf, cartId, etag, 1);
  if (patched.status === 412) {
    const reread = http.get(`${BASE}/v2/carts/${cartId}`, { jar: cj, redirects: 0 });
    etag = reread.headers['Etag'] || reread.headers['etag'] || etag;
    patched = patchQuantity(cj, csrf, cartId, etag, 1);
  }
  if (patched.body && patched.body.csrf) csrf = patched.body.csrf;
  if (patched.etag) etag = patched.etag;

  // Reservation
  let resv = reserve(cj, csrf, cartId);
  if (resv.status === 401 && isExpired({ status: 401, json: () => resv.body })) {
    const r = renew(cj, csrf);
    csrf = r.csrf;
    const rec = recoverCart(cj, csrf, cartId);
    if (rec.csrf) csrf = rec.csrf;
    resv = reserve(cj, csrf, cartId);
  }
  if (resv.body && resv.body.csrf) csrf = resv.body.csrf;
  let reservationId = null;
  if (resv.status === 202 && resv.body.status_url) {
    reservationId = pollReservation(cj, resv.body.status_url);
  }
  check(reservationId, { 'reservation ready': (r) => r !== null });

  // Checkout — this is where expiry is expected to hit
  const idemKey = `idem-${user}-${cartId}-${Date.now()}`;
  let order = placeOrder(cj, csrf, cartId, reservationId, idemKey, etag);

  if (order.status === 401 && isExpired({ status: 401, json: () => order.body })) {
    const err = order.body.error;
    if (err === 'expired') {
      const r = renew(cj, csrf);
      csrf = r.csrf;
      const rec = recoverCart(cj, csrf, cartId);
      if (rec.csrf) csrf = rec.csrf;
    } else {
      // session revoked: fresh login + recover
      csrf = login(cj, user);
      const rec = recoverCart(cj, csrf, cartId);
      if (rec.csrf) csrf = rec.csrf;
    }
    // retry interrupted operation once, same idempotency key
    order = placeOrder(cj, csrf, cartId, reservationId, idemKey, etag);
  }

  check(order, {
    'order accepted': (o) => o.status === 201 && o.body.accepted === true && o.body.id,
  });
}
