const PROFILES = [
  { job_polls: 2, poll_interval: 0.02 },
  { job_polls: 3, poll_interval: 0.02, html_layout: 1, reverse_catalog: true },
];

function sleep(ms) {
  const end = Date.now() + ms;
  while (Date.now() < end) { /* busy wait */ }
}

function parseCsrfFromForm(body) {
  // input[name=csrf] with possible attribute variants / decoys
  const re = /<input\b[^>]*\bname\s*=\s*["']?csrf["']?[^>]*>/gi;
  let m;
  while ((m = re.exec(body)) !== null) {
    const tag = m[0];
    const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  return null;
}

function parseChallengeForm(body) {
  const actionM = body.match(/<form\b[^>]*\baction\s*=\s*["']([^"']*\/v2\/challenges\/[^"']*)["']/i);
  const inputM = body.match(/<input\b[^>]*\bname\s*=\s*["']?challenge["']?[^>]*>/i);
  let challengeVal = null;
  if (inputM) {
    const vm = inputM[0].match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (vm) challengeVal = vm[1];
  }
  return { action: actionM ? actionM[1] : null, challenge: challengeVal };
}

function jar() {
  return http.cookieJar();
}

function getCsrfFromJson(res) {
  try {
    const j = res.json();
    if (j && typeof j.csrf === 'string') return j.csrf;
  } catch (e) {}
  return null;
}

function login(username, password) {
  const formRes = http.get(`${BASE}/v2/login-form`, { redirects: 0 });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const csrf = parseCsrfFromForm(formRes.body);
  check(csrf, { 'login csrf found': (c) => !!c });

  const loginRes = http.post(`${BASE}/v2/login`, JSON.stringify({ username, password, csrf }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
  });
  check(loginRes, { 'login ok': (r) => r.status === 200 || r.status === 302 });

  let token = getCsrfFromJson(loginRes);
  if (!token) {
    // follow dynamic Location once if 302
    if (loginRes.status === 302) {
      const loc = loginRes.headers['Location'] || loginRes.headers['location'];
      if (loc) {
        const followRes = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { redirects: 0 });
        token = getCsrfFromJson(followRes);
      }
    }
  }
  check(token, { 'session csrf': (t) => !!t });
  return token;
}

function fetchCatalog() {
  const res = http.get(`${BASE}/v2/catalog`, { redirects: 0 });
  check(res, { 'catalog 200': (r) => r.status === 200 });
  let products = [];
  try {
    const j = res.json();
    products = (j && j.data && j.data.products) || [];
  } catch (e) {}
  return products;
}

function pickProduct(products, reverse) {
  const list = reverse ? products.slice().reverse() : products;
  for (const p of list) {
    const variants = p.variants || [];
    for (const v of variants) {
      if (v.in_stock) return { product_id: p.id, variant_id: v.id };
    }
  }
  return null;
}

function obtainGrant(csrf) {
  const formRes = http.get(`${BASE}/v2/challenge-form`, { redirects: 0 });
  check(formRes, { 'challenge-form 200': (r) => r.status === 200 });
  const { action, challenge } = parseChallengeForm(formRes.body);
  check(action, { 'challenge action': (a) => !!a });
  check(challenge, { 'challenge value': (c) => !!c });
  if (!action || !challenge) return null;

  const postRes = http.post(action.startsWith('http') ? action : `${BASE}${action}`,
    JSON.stringify({ challenge }),
    { headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }, redirects: 0 });
  check(postRes, { 'challenge post 302': (r) => r.status === 302 });
  const loc = postRes.headers['Location'] || postRes.headers['location'];
  if (!loc) return null;
  const followRes = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { redirects: 0 });
  check(followRes, { 'challenge follow 200': (r) => r.status === 200 });
  let grant = null;
  try {
    const j = followRes.json();
    grant = j && j.grant_id;
  } catch (e) {}
  check(grant, { 'grant_id': (g) => !!g });
  return grant;
}

function createCart(csrf, product_id, variant_id, grant_id) {
  const body = { product_id, variant_id };
  if (grant_id) body.grant_id = grant_id;
  const res = http.post(`${BASE}/v2/carts`, JSON.stringify(body), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  check(res, { 'cart 201': (r) => r.status === 201 });
  let id = null, newCsrf = null, etag = res.headers['Etag'] || res.headers['ETag'] || res.headers['etag'];
  try {
    const j = res.json();
    id = j && j.id;
    newCsrf = j && j.csrf;
  } catch (e) {}
  check(id, { 'cart id': (i) => !!i });
  return { id, csrf: newCsrf || csrf, etag };
}

function patchCart(csrf, cartId, etag, quantity) {
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
  };
  if (etag) headers['If-Match'] = etag;
  let res = http.patch(`${BASE}/v2/carts/${cartId}`, JSON.stringify({ quantity }), {
    headers, redirects: 0,
  });
  if (res.status === 412) {
    const re = http.get(`${BASE}/v2/carts/${cartId}`, { redirects: 0 });
    const newEtag = re.headers['Etag'] || re.headers['ETag'] || re.headers['etag'];
    const h2 = Object.assign({}, headers);
    if (newEtag) h2['If-Match'] = newEtag;
    res = http.patch(`${BASE}/v2/carts/${cartId}`, JSON.stringify({ quantity }), {
      headers: h2, redirects: 0,
    });
  }
  check(res, { 'patch ok': (r) => r.status === 200 || r.status === 204 });
  let newCsrf = getCsrfFromJson(res);
  return { csrf: newCsrf || csrf, etag: res.headers['Etag'] || res.headers['ETag'] || res.headers['etag'] };
}

function startReservation(csrf, cartId) {
  const res = http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  check(res, { 'reservation 202': (r) => r.status === 202 });
  let status_url = null, newCsrf = null;
  try {
    const j = res.json();
    status_url = j && j.status_url;
    newCsrf = j && j.csrf;
  } catch (e) {}
  check(status_url, { 'status_url': (u) => !!u });
  return { status_url, csrf: newCsrf || csrf };
}

function pollReservation(csrf, status_url, maxPolls, intervalSec) {
  let reservation_id = null;
  let lastStatus = null;
  let polls = 0;
  const cap = Math.min(maxPolls, 5);
  while (polls < cap) {
    if (polls > 0) sleep(intervalSec * 1000);
    polls++;
    const url = status_url.startsWith('http') ? status_url : `${BASE}${status_url}`;
    const res = http.get(url, { redirects: 0 });
    check(res, { 'poll 200': (r) => r.status === 200 });
    let status = null, rid = null, newCsrf = null;
    try {
      const j = res.json();
      status = j && j.status;
      rid = j && j.reservation_id;
      newCsrf = j && j.csrf;
    } catch (e) {}
    if (newCsrf) csrf = newCsrf;
    lastStatus = status;
    if (status === 'ready') {
      reservation_id = rid;
      break;
    }
    if (status === 'failed') break;
  }
  check(polls, { 'polls <= 5': (p) => p <= 5 });
  return { reservation_id, status: lastStatus, csrf, polls };
}

function placeOrder(csrf, cartId, reservation_id, etag) {
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': `idem-${cartId}-${Date.now()}`,
  };
  if (etag) headers['If-Match'] = etag;
  const body = { cart_id: cartId };
  if (reservation_id) body.reservation_id = reservation_id;
  const res = http.post(`${BASE}/v2/orders`, JSON.stringify(body), {
    headers, redirects: 0,
  });
  check(res, { 'order 201': (r) => r.status === 201 });
  let accepted = false, orderId = null;
  try {
    const j = res.json();
    accepted = j && j.accepted === true;
    orderId = j && j.id;
  } catch (e) {}
  check(accepted, { 'order accepted': (a) => a === true });
  check(orderId, { 'order id': (i) => !!i });
  return { accepted, orderId };
}

export default function () {
  const vu = __VU;
  const iter = __ITER;
  const profile = PROFILES[(vu + iter) % PROFILES.length];
  const username = `bench-${((vu - 1) % 16) + 1}`;
  const password = 'bench';

  jar().clear(BASE);

  const csrf0 = login(username, password);
  if (!csrf0) return;

  const products = fetchCatalog();
  const pick = pickProduct(products, !!profile.reverse_catalog);
  check(pick, { 'product picked': (p) => !!p });
  if (!pick) return;

  const grant = obtainGrant(csrf0);
  if (!grant) return;

  const cart = createCart(csrf0, pick.product_id, pick.variant_id, grant);
  if (!cart.id) return;

  const patched = patchCart(cart.csrf, cart.id, cart.etag, 1);

  const resv = startReservation(patched.csrf, cart.id);
  if (!resv.status_url) return;

  const polled = pollReservation(resv.csrf, resv.status_url, profile.job_polls, profile.poll_interval);

  // Safety: never checkout pending/failed
  if (polled.status !== 'ready' || !polled.reservation_id) {
    check(polled, { 'skip checkout on non-ready': () => true });
    return;
  }

  placeOrder(polled.csrf, cart.id, polled.reservation_id, patched.etag);
}
