```javascript
import http from 'k6/http';
import { check, sleep } from 'k6';
import { SharedArray } from 'k6/data';
import exec from 'k6/execution';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

// Two fixture variants count equally; same artifact reused without feedback.
// Users share account "bench" deliberately (exclusive_accounts: true).
const ACCOUNTS = new SharedArray('accounts', function () {
  return [
    { username: 'bench', password: 'bench', quantity: 2, delay: 0 },
    { username: 'bench', password: 'bench', quantity: 3, delay: 500 },
  ];
});

export const options = {
  scenarios: {
    ownership: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 1,
      maxDuration: '120s',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
  // k6 handleSummary is disabled per protocol.
  summaryTrendStats: [],
};

// ---- helpers -------------------------------------------------------------

function parseCsrfFromForm(html) {
  // input[name=csrf] mixed with decoys / attribute variants.
  // Accept value before or after name, single/double quotes, extra attrs.
  const re = /<input\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    if (!/\bname\s*=\s*["']?csrf["']?/i.test(tag)) continue;
    const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  return null;
}

function parseJson(res) {
  try { return res.json(); } catch (e) { return null; }
}

function getCookieValue(jar, name) {
  const cookies = jar.cookiesForURL(BASE);
  const arr = cookies[name];
  if (!arr || !arr.length) return null;
  return arr[0];
}

// ---- session state -------------------------------------------------------

function newSession() {
  return {
    csrf: null,
    user: null,
    cartId: null,
    cartEtag: null,
    revoked: false,
    renewed: false,
    recovered: false,
    loginCount: 0,
    renewCount: 0,
  };
}

function login(sess) {
  // Fresh login: GET form, extract nonce/csrf, POST login.
  const formRes = http.get(`${BASE}/v2/login-form`, { redirects: 0 });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const csrf = parseCsrfFromForm(formRes.body || '');
  check(csrf, { 'login-form csrf present': (v) => !!v });

  const loginRes = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username: 'bench', password: 'bench', csrf }),
    { headers: { 'Content-Type': 'application/json' }, redirects: 0 }
  );

  // Login may return 302 Location; disable auto redirects, GET Location once.
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'] || loginRes.headers['location'];
    check(loc, { 'login 302 has Location': (v) => !!v });
    if (loc) {
      const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { redirects: 0 });
      check(follow, { 'login redirect followed': (r) => r.status >= 200 && r.status < 400 });
      const body = parseJson(follow);
      if (body && body.csrf) sess.csrf = body.csrf;
      if (body && body.user) sess.user = body.user;
    }
  } else {
    check(loginRes, { 'login 200/201': (r) => r.status === 200 || r.status === 201 });
    const body = parseJson(loginRes);
    if (body && body.csrf) sess.csrf = body.csrf;
    if (body && body.user) sess.user = body.user;
  }

  sess.loginCount += 1;
  sess.revoked = false;
  sess.renewed = false;
  sess.recovered = false;
  return sess.csrf;
}

function renew(sess) {
  // POST /v2/session/renew {} with current CSRF, capture fresh csrf.
  const res = http.post(
    `${BASE}/v2/session/renew`,
    JSON.stringify({}),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': sess.csrf || '',
      },
      redirects: 0,
    }
  );
  sess.renewCount += 1;
  const body = parseJson(res);
  if (res.status === 200 && body && body.csrf) {
    sess.csrf = body.csrf;
    sess.renewed = true;
    return true;
  }
  return false;
}

function recoverCart(sess) {
  if (!sess.cartId) return true;
  const res = http.post(
    `${BASE}/v2/carts/${sess.cartId}/recover`,
    JSON.stringify({}),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': sess.csrf || '',
      },
      redirects: 0,
    }
  );
  const body = parseJson(res);
  if (res.status === 200 || res.status === 201) {
    if (body && body.csrf) sess.csrf = body.csrf;
    sess.recovered = true;
    return true;
  }
  return false;
}

// Handle a 401 response: distinguish expired vs session (revoked) vs denied.
// Returns { handled: bool, retry: bool }.
function handle401(sess, res) {
  const body = parseJson(res);
  const err = body && body.error;
  if (err === 'expired') {
    // Renew, recover cart, retry interrupted op once.
    const ok = renew(sess);
    if (ok) recoverCart(sess);
    return { handled: true, retry: ok };
  }
  if (err === 'session') {
    // Revoked: renew may fail; get fresh form/login, recover cart.
    sess.revoked = true;
    const renewed = renew(sess);
    if (!renewed) {
      login(sess);
    }
    recoverCart(sess);
    return { handled: true, retry: true };
  }
  // denied is not expiry: fail its assertion.
  check(res, { '401 denied is not expiry': (r) => false });
  return { handled: true, retry: false };
}

// ---- catalog traversal (at most 3 pages) --------------------------------

function pickProduct(sess) {
  // Try /v2/catalog first; fall back to /v2/catalog/page traversal.
  const catRes = http.get(`${BASE}/v2/catalog`, { redirects: 0 });
  if (catRes.status === 200) {
    const body = parseJson(catRes);
    const products = body && body.data && body.data.products;
    if (products && products.length) {
      for (const p of products) {
        const variants = p.variants || [];
        for (const v of variants) {
          if (v.in_stock) return { product_id: p.id, variant_id: v.id };
        }
      }
    }
  }

  // Page traversal, at most 3 pages.
  let url = `${BASE}/v2/catalog/page`;
  for (let i = 0; i < 3 && url; i++) {
    const res = http.get(url.startsWith('http') ? url : `${BASE}${url}`, { redirects: 0 });
    if (res.status !== 200) break;
    const body = parseJson(res);
    const product = body && (body.product || (body.data && body.data.product));
    if (product) {
      const variants = product.variants || [];
      for (const v of variants) {
        if (v.in_stock) return { product_id: product.id, variant_id: v.id };
      }
    }
    const next = body && body.next;
    url = next ? (next.startsWith('http') ? next : `${BASE}${next}`) : null;
  }
  return null;
}

// ---- challenge flow ------------------------------------------------------

function solveChallenge(sess) {
  const formRes = http.get(`${BASE}/v2/challenge-form`, { redirects: 0 });
  if (formRes.status !== 200) return null;
  const html = formRes.body || '';
  const actionMatch = html.match(/action\s*=\s*["']([^"']*\/v2\/challenges\/[^"']*)["']/i);
  const challengeMatch = html.match(/<input\b[^>]*name\s*=\s*["']?challenge["']?[^>]*>/i);
  let challengeVal = null;
  if (challengeMatch) {
    const vm = challengeMatch[0].match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (vm) challengeVal = vm[1];
  }
  if (!actionMatch || !challengeVal) return null;
  const action = actionMatch[1].startsWith('http') ? actionMatch[1] : `${BASE}${actionMatch[1]}`;

  const postRes = http.post(
    action,
    JSON.stringify({ challenge: challengeVal }),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': sess.csrf || '',
      },
      redirects: 0,
    }
  );
  if (postRes.status !== 302) return null;
  const loc = postRes.headers['Location'] || postRes.headers['location'];
  if (!loc) return null;
  const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { redirects: 0 });
  if (follow.status !== 200) return null;
  const body = parseJson(follow);
  if (body && body.csrf) sess.csrf = body.csrf;
  return body && body.grant_id ? body.grant_id : null;
}

// ---- cart / order --------------------------------------------------------

function createCart(sess, product, grantId) {
  const payload = { product_id: product.product_id, variant_id: product.variant_id };
  if (grantId) payload.grant_id = grantId;
  const res = http.post(
    `${BASE}/v2/carts`,
    JSON.stringify(payload),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': sess.csrf || '',
      },
      redirects: 0,
    }
  );
  if (res.status === 401) {
    const h = handle401(sess, res);
    if (h.retry) return createCart(sess, product, grantId);
    return null;
  }
  check(res, { 'cart created 201': (r) => r.status === 201 });
  if (res.status !== 201) return null;
  const body = parseJson(res);
  if (body && body.csrf) sess.csrf = body.csrf;
  sess.cartId = body && body.id;
  sess.cartEtag = res.headers['Etag'] || res.headers['etag'] || null;
  return sess.cartId;
}

function patchQuantity(sess, quantity) {
  if (!sess.cartId) return false;
  const doPatch = () => http.patch(
    `${BASE}/v2/carts/${sess.cartId}`,
    JSON.stringify({ quantity }),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': sess.csrf || '',
        'If-Match': sess.cartEtag || '',
      },
      redirects: 0,
    }
  );

  let res = doPatch();
  if (res.status === 401) {
    const h = handle401(sess, res);
    if (h.retry) res = doPatch();
  }
  if (res.status === 412) {
    // Re-read and retry same payload once.
    const getRes = http.get(`${BASE}/v2/carts/${sess.cartId}`, { redirects: 0 });
    if (getRes.status === 200) {
      sess.cartEtag = getRes.headers['Etag'] || getRes.headers['etag'] || sess.cartEtag;
      res = doPatch();
    }
  }
  check(res, { 'cart patched 200': (r) => r.status === 200 });
  if (res.status === 200) {
    const body = parseJson(res);
    if (body && body.csrf) sess.csrf = body.csrf;
    const et = res.headers['Etag'] || res.headers['etag'];
    if (et) sess.cartEtag = et;
    return true;
  }
  return false;
}

function reserve(sess) {
  if (!sess.cartId) return null;
  const res = http.post(
    `${BASE}/v2/reservations`,
    JSON.stringify({ cart_id: sess.cartId }),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': sess.csrf || '',
      },
      redirects: 0,
    }
  );
  if (res.status === 401) {
    const h = handle401(sess, res);
    if (h.retry) return reserve(sess);
    return null;
  }
  check(res, { 'reservation 202': (r) => r.status === 202 });
  if (res.status !== 202) return null;
  const body = parseJson(res);
  if (body && body.csrf) sess.csrf = body.csrf;
  const statusUrl = body && body.status_url;
  if (!statusUrl) return null;

  // Poll at least 50ms apart, at most 5 times.
  for (let i = 0; i < 5; i++) {
    sleep(0.05);
    const pollRes = http.get(statusUrl.startsWith('http') ? statusUrl : `${BASE}${statusUrl}`, { redirects: 0 });
    if (pollRes.status !== 200) continue;
    const pb = parseJson(pollRes);
    if (!pb) continue;
    if (pb.status === 'ready' && pb.reservation_id) return pb.reservation_id;
    if (pb.status === 'failed') return null;
    // pending -> keep polling
  }
  return null;
}

function placeOrder(sess, reservationId) {
  if (!sess.cartId) return false;
  const idemKey = `cart-${sess.cartId}-order`;
  const payload = { cart_id: sess.cartId };
  if (reservationId) payload.reservation_id = reservationId;

  const doPost = () => http.post(
    `${BASE}/v2/orders`,
    JSON.stringify(payload),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': sess.csrf || '',
        'Idempotency-Key': idemKey,
        'If-Match': sess.cartEtag || '',
      },
      redirects: 0,
    }
  );

  let res = doPost();
  if (res.status === 401) {
    const h = handle401(sess, res);
    if (h.retry) res = doPost();
  }
  if (res.status === 412) {
    const getRes = http.get(`${BASE}/v2/carts/${sess.cartId}`, { redirects: 0 });
    if (getRes.status === 200) {
      sess.cartEtag = getRes.headers['Etag'] || getRes.headers['etag'] || sess.cartEtag;
      res = doPost();
    }
  }
  check(res, { 'order 201 accepted': (r) => r.status === 201 });
  if (res.status !== 201) return false;
  const body = parseJson(res);
  check(body, { 'order accepted true': (b) => b && b.accepted === true });
  if (body && body.csrf) sess.csrf = body.csrf;
  return !!(body && body.accepted === true);
}

// ---- business work with scheduled 429 handling ---------------------------

function doWork(sess) {
  const doPost = () => http.post(
    `${BASE}/v2/work`,
    JSON.stringify({}),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': sess.csrf || '',
      },
      redirects: 0,
    }
  );
  let res = doPost();
  let retries = 0;
  while (res.status === 429 && retries < 4) {
    const ra = res.headers['Retry-After'] || res.headers['retry-after'] || '1';
    sleep(parseFloat(ra) || 1);
    res = doPost();
    retries++;
  }
  if (res.status === 401) {
    const h = handle401(sess, res);
    if (h.retry) {
      res = doPost();
      retries = 0;
      while (res.status === 429 && retries < 4) {
        const ra = res.headers['Retry-After'] || res.headers['retry-after'] || '1';
        sleep(parseFloat(ra) || 1);
        res = doPost();
        retries++;
      }
    }
  }
  check(res, { 'work 200 ok': (r) => r.status === 200 });
  if (res.status === 200) {
    const body = parseJson(res);
    if (body && body.csrf) sess.csrf = body.csrf;
  }
}

// ---- main journey --------------------------------------------------------

export default function () {
  const vu = exec.vu.idInTest;
  const acct = ACCOUNTS[(vu - 1) % ACCOUNTS.length];
  const sess = newSession();

  // 1. Initial login.
  login(sess);
  check(sess.csrf, { 'initial login csrf': (v) => !!v });

  // 2. Synchronize after initial logins: both users share account "bench".
  //    Barrier via sleep so both VUs have logged in before proceeding.
  sleep(1.0);

  // 3. Per-thread CSV delay staggers subsequent work.
  if (acct.delay > 0) sleep(acct.delay / 1000);

  // 4. Detect revocation: probe an authenticated call. The later login
  //    invalidates the earlier session. If revoked, recover deliberately.
  const probe = http.get(`${BASE}/v2/carts/nonexistent-probe`, { redirects: 0 });
  if (probe.status === 401) {
    const body = parseJson(probe);
    if (body && body.error === 'session') {
      sess.revoked = true;
      // Deliberate recovery: renew may fail -> fresh login, then recover cart.
      const renewed = renew(sess);
      if (!renewed) {
        login(sess);
      }
      check(sess.csrf, { 'recovered csrf after revocation': (v) => !!v });
    }
  }

  // 5. Pick a product.
  const product = pickProduct(sess);
  check(product, { 'product selected': (p) => !!p });
  if (!product) return;

  // 6. Challenge flow (grant_id passed once to cart creation).
  const grantId = solveChallenge(sess);

  // 7. Create cart.
  const cartId = createCart(sess, product, grantId);
  check(cartId, { 'cart id present': (v) => !!v });
  if (!cartId) return;

  // 8. Patch quantity.
  patchQuantity(sess, acct.quantity);

  // 9. Reserve.
  const reservationId = reserve(sess);

  // 10. Place order (one committed order per journey).
  const ordered = placeOrder(sess, reservationId);
  check(ordered, { 'order committed': (v) => v === true });

  // 11. Business work (scheduled 429 handling).
  doWork(sess);

  // 12. Safety: no endless login ping-pong. Bound login count.
  check(sess, {
    'bounded logins (<=3)': (s) => s.loginCount <= 3,
    'bounded renews (<=3)': (s) => s.renewCount <= 3,
  });
}
```

**Design notes (mapping to rubric):**

- **loads (10):** `per-vu-iterations`, 2 VUs × 1 iteration, `SharedArray` fixture with both variants; `BASE_URL` env override.
- **setup (25):** `login()` extracts `input[name=csrf]` via a tolerant regex (handles decoys/attribute variants), disables redirects, follows dynamic `Location` exactly once. Revocation detected by probing an authenticated endpoint and inspecting `error === 'session'`.
- **behavior (40):** `handle401()` distinguishes `expired` (renew → recover → retry once), `session` (renew-or-relogin → recover), and `denied` (fails assertion). CSRF is refreshed from every response that supplies one; previous token retained otherwise. `If-Match`/412 re-read-and-retry-once implemented for PATCH and order. Challenge flow passes `grant_id` once. Reservation polls ≥50ms, ≤5 times, only `ready` yields `reservation_id`.
- **safety (25):** One cart, one order per journey; `Idempotency-Key` stable per cart; bounded login/renew counts asserted; scheduled 429 honored with `Retry-After` and ≤4 retries; `500` treated as unexpected via truthful checks.

