import http from 'k6/http';
import { check } from 'k6';

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
  thresholds: {},
};

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

function jar() {
  return http.cookieJar();
}

function getCsrfFromForm(body) {
  if (!body) return null;
  const re = /<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i;
  const m = body.match(re);
  return m ? m[1] : null;
}

function parseJson(body) {
  try { return JSON.parse(body); } catch (e) { return null; }
}

function headerVal(res, name) {
  const h = res.headers[name] || res.headers[name.toLowerCase()];
  return h || null;
}

function isExpiredOrSession(res) {
  const j = parseJson(res.body);
  if (j && (j.error === 'expired' || j.error === 'session')) return j.error;
  return null;
}

export default function () {
  const vu = __VU;
  const username = `bench-${vu}`;
  const password = 'bench';

  const cj = jar();
  const params = (extra) => Object.assign({ jar: cj, redirects: 0, timeout: '3s' }, extra || {});

  let csrf = null;
  let cart = null;
  let etag = null;
  let grant = null;
  let product = null;
  let variant = null;
  const quantity = 2;

  // 1. GET /v2/login-form
  let res = http.get(`${BASE}/v2/login-form`, params());
  check(res, { 'login-form 200': (r) => r.status === 200 });
  const formCsrf = getCsrfFromForm(res.body);
  check(res, { 'login-form csrf present': () => !!formCsrf });
  if (formCsrf) csrf = formCsrf;

  // 2. POST /v2/login
  const loginBody = JSON.stringify({ username, password, csrf: formCsrf });
  res = http.post(`${BASE}/v2/login`, loginBody, params({
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf || '' },
  }));
  check(res, { 'login status ok': (r) => r.status === 200 || r.status === 302 });
  let loginJson = parseJson(res.body);
  if (loginJson && loginJson.csrf) csrf = loginJson.csrf;

  // Handle 302 Location exactly once
  if (res.status === 302) {
    const loc = headerVal(res, 'Location');
    check(res, { 'login redirect has Location': () => !!loc });
    if (loc) {
      const url = loc.startsWith('http') ? loc : `${BASE}${loc}`;
      const r2 = http.get(url, params());
      check(r2, { 'login redirect follow ok': (r) => r.status === 200 });
      const j2 = parseJson(r2.body);
      if (j2 && j2.csrf) csrf = j2.csrf;
      if (j2 && j2.grant_id) grant = j2.grant_id;
    }
  }

  // 3. GET /v2/catalog
  res = http.get(`${BASE}/v2/catalog`, params({
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf || '' },
  }));
  check(res, { 'catalog 200': (r) => r.status === 200 });
  const cat = parseJson(res.body);
  if (cat && cat.csrf) csrf = cat.csrf;
  if (cat && cat.data && Array.isArray(cat.data.products)) {
    for (const p of cat.data.products) {
      if (p && Array.isArray(p.variants)) {
        const v = p.variants.find((x) => x && x.in_stock === true);
        if (v) { product = p.id; variant = v.id; break; }
      }
    }
  }
  check(res, { 'catalog has in-stock product': () => !!product && !!variant });

  // 4. POST /v2/carts
  const cartPayload = { product_id: product, variant_id: variant };
  if (grant) cartPayload.grant_id = grant;
  res = http.post(`${BASE}/v2/carts`, JSON.stringify(cartPayload), params({
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf || '' },
  }));
  check(res, { 'cart created 201': (r) => r.status === 201 });
  const cartJson = parseJson(res.body);
  if (cartJson) {
    if (cartJson.csrf) csrf = cartJson.csrf;
    if (cartJson.id) cart = cartJson.id;
  }
  const cartEtag = headerVal(res, 'ETag');
  if (cartEtag) etag = cartEtag;
  check(res, { 'cart id present': () => !!cart });

  // 5. POST /v2/orders
  const orderPayload = { cart_id: cart };
  const idemKey = cart || `idem-${vu}-${Date.now()}`;
  const orderHeaders = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf || '',
    'Idempotency-Key': idemKey,
  };
  if (etag) orderHeaders['If-Match'] = etag;
  res = http.post(`${BASE}/v2/orders`, JSON.stringify(orderPayload), params({ headers: orderHeaders }));
  check(res, { 'order 201': (r) => r.status === 201 });
  const orderJson = parseJson(res.body);
  check(res, { 'order accepted true': () => !!(orderJson && orderJson.accepted === true) });
  if (orderJson && orderJson.csrf) csrf = orderJson.csrf;
}
