import http from 'k6/http';
import { check } from 'k6';

export const options = {
  scenarios: {
    journey: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '2m',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

function jar() {
  return new http.CookieJar();
}

function parseCsrfFromForm(body) {
  if (!body) return null;
  const re = /<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i;
  const m = body.match(re);
  return m ? m[1] : null;
}

function safeJson(res) {
  try { return res.json(); } catch (e) { return null; }
}

function getHeader(res, name) {
  const h = res.headers[name] || res.headers[name.toLowerCase()];
  return h || null;
}

function pickProduct(catalog) {
  if (!catalog || !catalog.data || !Array.isArray(catalog.data.products)) return null;
  for (const p of catalog.data.products) {
    if (!p || !Array.isArray(p.variants)) continue;
    for (const v of p.variants) {
      if (v && v.in_stock === true) {
        return { product: p.id, variant: v.id };
      }
    }
  }
  return null;
}

function loginAndGetSession(cookies, username) {
  const formRes = http.get(`${BASE}/v2/login-form`, { jar: cookies, redirects: 0 });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const formCsrf = parseCsrfFromForm(formRes.body);
  check(formCsrf, { 'form csrf extracted': (v) => !!v });
  if (!formCsrf) return null;

  const loginRes = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username, password: 'bench', csrf: formCsrf }),
    { jar: cookies, redirects: 0, headers: { 'Content-Type': 'application/json' } }
  );

  let csrf = null;
  let grant = null;

  if (loginRes.status === 302) {
    const loc = getHeader(loginRes, 'Location');
    check(loc, { 'login Location present': (v) => !!v });
    if (!loc) return null;
    const followRes = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, {
      jar: cookies,
      redirects: 0,
    });
    check(followRes, { 'redirect follow 200': (r) => r.status === 200 });
    const j = safeJson(followRes);
    if (j) {
      csrf = j.csrf || null;
      grant = j.grant_id || null;
    }
  } else {
    const j = safeJson(loginRes);
    if (j) {
      csrf = j.csrf || null;
      grant = j.grant_id || null;
    }
  }

  check(csrf, { 'session csrf present': (v) => !!v });
  return { csrf, grant };
}

function fetchChallenge(cookies, csrf) {
  const formRes = http.get(`${BASE}/v2/challenge-form`, { jar: cookies, redirects: 0 });
  check(formRes, { 'challenge-form 200': (r) => r.status === 200 });
  const body = formRes.body || '';
  const actionMatch = body.match(/action=["']([^"']*\/v2\/challenges\/[^"']+)["']/i);
  const challengeMatch = body.match(/<input(?=[^>]*\bname=["']challenge["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i);
  const action = actionMatch ? actionMatch[1] : null;
  const challenge = challengeMatch ? challengeMatch[1] : null;
  check(action, { 'challenge action extracted': (v) => !!v });
  check(challenge, { 'challenge value extracted': (v) => !!v });
  if (!action || !challenge) return null;

  const actionUrl = action.startsWith('http') ? action : `${BASE}${action}`;
  const postRes = http.post(
    actionUrl,
    JSON.stringify({ challenge }),
    {
      jar: cookies,
      redirects: 0,
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    }
  );
  check(postRes, { 'challenge post 302': (r) => r.status === 302 });
  const loc = getHeader(postRes, 'Location');
  check(loc, { 'challenge Location present': (v) => !!v });
  if (!loc) return null;

  const followRes = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, {
    jar: cookies,
    redirects: 0,
  });
  check(followRes, { 'challenge follow 200': (r) => r.status === 200 });
  const j = safeJson(followRes);
  const grant = j && j.grant_id ? j.grant_id : null;
  const newCsrf = j && j.csrf ? j.csrf : csrf;
  check(grant, { 'grant_id extracted': (v) => !!v });
  return { grant, csrf: newCsrf };
}

export default function () {
  const cookies = jar();
  const username = `bench-${__VU}`;

  const session = loginAndGetSession(cookies, username);
  if (!session) return;
  let csrf = session.csrf;
  let grant = session.grant;

  if (!grant) {
    const ch = fetchChallenge(cookies, csrf);
    if (!ch) return;
    grant = ch.grant;
    csrf = ch.csrf;
  }

  const catRes = http.get(`${BASE}/v2/catalog`, { jar: cookies, redirects: 0 });
  check(catRes, { 'catalog 200': (r) => r.status === 200 });
  const cat = safeJson(catRes);
  const pick = pickProduct(cat);
  check(pick, { 'in-stock product found': (v) => !!v });
  if (!pick) return;

  const cartRes = http.post(
    `${BASE}/v2/carts`,
    JSON.stringify({ product_id: pick.product, variant_id: pick.variant, grant_id: grant }),
    {
      jar: cookies,
      redirects: 0,
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    }
  );
  check(cartRes, { 'cart created 201': (r) => r.status === 201 });
  const cartJson = safeJson(cartRes);
  const cartId = cartJson && cartJson.id ? cartJson.id : null;
  if (cartJson && cartJson.csrf) csrf = cartJson.csrf;
  check(cartId, { 'cart id present': (v) => !!v });
  if (!cartId) return;

  const orderRes = http.post(
    `${BASE}/v2/orders`,
    JSON.stringify({ cart_id: cartId }),
    {
      jar: cookies,
      redirects: 0,
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
        'Idempotency-Key': cartId,
      },
    }
  );
  check(orderRes, { 'order 201': (r) => r.status === 201 });
  const orderJson = safeJson(orderRes);
  check(orderJson, { 'order accepted true': (j) => j && j.accepted === true });
}
