// accounts.json rows, one per VU (index = __VU - 1)
const ACCOUNTS = [
  { username: 'bench-1', password: 'bench', quantity: 2, delay: 0 },
  { username: 'bench-2', password: 'bench', quantity: 3, delay: 500 },
];

function sleep(ms) {
  if (ms > 0) {
    const end = Date.now() + ms;
    while (Date.now() < end) { /* busy wait */ }
  }
}

function parseCsrfFromForm(body) {
  // input[name=csrf] with value, tolerant of attribute order / quotes
  const re = /<input\b[^>]*>/gi;
  let m;
  while ((m = re.exec(body)) !== null) {
    const tag = m[0];
    const nameM = tag.match(/\bname\s*=\s*["']([^"']+)["']/i);
    if (!nameM || nameM[1] !== 'csrf') continue;
    const valM = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (valM) return valM[1];
  }
  return null;
}

function getHeader(res, name) {
  const h = res.headers[name] || res.headers[name.toLowerCase()];
  return h || null;
}

function jsonBody(res) {
  try { return res.json(); } catch (e) { return null; }
}

export default function () {
  const acct = ACCOUNTS[(__VU - 1) % ACCOUNTS.length];
  const quantity = acct.quantity; // numeric, preserved
  const jar = http.cookieJar();

  // Fresh login/cart each journey
  jar.clear(BASE);

  // 1. login form
  let res = http.get(`${BASE}/v2/login-form`, { redirects: 0 });
  check(res, { 'login-form 200': (r) => r.status === 200 });
  let csrf = parseCsrfFromForm(res.body);
  check(csrf, { 'csrf from form': (v) => !!v });

  // 2. login
  res = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username: acct.username, password: acct.password, csrf }),
    { headers: { 'Content-Type': 'application/json' }, redirects: 0 }
  );
  check(res, { 'login ok': (r) => r.status === 200 || r.status === 302 });
  let body = jsonBody(res);
  if (body && body.csrf) csrf = body.csrf;

  // follow dynamic Location exactly once if 302
  if (res.status === 302) {
    const loc = getHeader(res, 'Location');
    check(loc, { 'login location present': (v) => !!v });
    if (loc) {
      const url = loc.startsWith('http') ? loc : `${BASE}${loc}`;
      res = http.get(url, { redirects: 0 });
      check(res, { 'login redirect ok': (r) => r.status === 200 });
      body = jsonBody(res);
      if (body && body.csrf) csrf = body.csrf;
    }
  }

  // 3. catalog
  res = http.get(`${BASE}/v2/catalog`, { redirects: 0 });
  check(res, { 'catalog 200': (r) => r.status === 200 });
  const cat = jsonBody(res);
  let product = null;
  let variant = null;
  if (cat && cat.data && Array.isArray(cat.data.products)) {
    for (const p of cat.data.products) {
      if (p.variants && p.variants.length) {
        const v = p.variants.find((x) => x.in_stock === true);
        if (v) { product = p.id; variant = v.id; break; }
      }
    }
  }
  check(product && variant, { 'in-stock product found': (v) => !!v });

  // 4. challenge for grant
  res = http.get(`${BASE}/v2/challenge-form`, { redirects: 0 });
  check(res, { 'challenge-form 200': (r) => r.status === 200 });
  let grant = null;
  const actionM = res.body.match(/action\s*=\s*["']([^"']*\/v2\/challenges\/[^"']+)["']/i);
  const challengeM = res.body.match(/<input\b[^>]*\bname\s*=\s*["']challenge["'][^>]*\bvalue\s*=\s*["']([^"']*)["']/i)
    || res.body.match(/<input\b[^>]*\bvalue\s*=\s*["']([^"']*)["'][^>]*\bname\s*=\s*["']challenge["']/i);
  if (actionM && challengeM) {
    const action = actionM[1].startsWith('http') ? actionM[1] : `${BASE}${actionM[1]}`;
    res = http.post(
      action,
      JSON.stringify({ challenge: challengeM[1] }),
      { headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }, redirects: 0 }
    );
    check(res, { 'challenge post 302': (r) => r.status === 302 });
    const loc = getHeader(res, 'Location');
    if (loc) {
      const url = loc.startsWith('http') ? loc : `${BASE}${loc}`;
      res = http.get(url, { redirects: 0 });
      check(res, { 'challenge location 200': (r) => r.status === 200 });
      body = jsonBody(res);
      if (body) {
        if (body.csrf) csrf = body.csrf;
        if (body.grant_id) grant = body.grant_id;
      }
    }
  }
  check(grant, { 'grant obtained': (v) => !!v });

  // 5. create cart
  const cartPayload = { product_id: product, variant_id: variant };
  if (grant) cartPayload.grant_id = grant;
  res = http.post(
    `${BASE}/v2/carts`,
    JSON.stringify(cartPayload),
    { headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }, redirects: 0 }
  );
  check(res, { 'cart created 201': (r) => r.status === 201 });
  body = jsonBody(res);
  const cartId = body && body.id;
  if (body && body.csrf) csrf = body.csrf;
  let etag = getHeader(res, 'ETag');
  check(cartId, { 'cart id present': (v) => !!v });

  // 6. PATCH quantity with If-Match, retry once on 412
  const patchPayload = JSON.stringify({ quantity });
  const patchHeaders = () => ({
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'If-Match': etag || '',
  });
  res = http.patch(`${BASE}/v2/carts/${cartId}`, patchPayload, { headers: patchHeaders(), redirects: 0 });
  if (res.status === 412) {
    // re-read
    const r2 = http.get(`${BASE}/v2/carts/${cartId}`, { redirects: 0 });
    const e2 = getHeader(r2, 'ETag');
    if (e2) etag = e2;
    res = http.patch(`${BASE}/v2/carts/${cartId}`, patchPayload, { headers: patchHeaders(), redirects: 0 });
  }
  check(res, { 'patch ok': (r) => r.status === 200 || r.status === 204 });
  body = jsonBody(res);
  if (body && body.csrf) csrf = body.csrf;
  const e3 = getHeader(res, 'ETag');
  if (e3) etag = e3;

  // 7. reservation
  res = http.post(
    `${BASE}/v2/reservations`,
    JSON.stringify({ cart_id: cartId }),
    { headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }, redirects: 0 }
  );
  check(res, { 'reservation 202': (r) => r.status === 202 });
  body = jsonBody(res);
  if (body && body.csrf) csrf = body.csrf;
  const statusUrl = body && body.status_url;
  check(statusUrl, { 'status_url present': (v) => !!v });

  let reservationId = null;
  if (statusUrl) {
    const url = statusUrl.startsWith('http') ? statusUrl : `${BASE}${statusUrl}`;
    for (let i = 0; i < 5; i++) {
      sleep(60);
      const r = http.get(url, { redirects: 0 });
      const b = jsonBody(r);
      if (b && b.status === 'ready' && b.reservation_id) {
        reservationId = b.reservation_id;
        if (b.csrf) csrf = b.csrf;
        break;
      }
      if (b && (b.status === 'failed')) break;
    }
  }
  check(reservationId, { 'reservation ready': (v) => !!v });

  // 8. order
  const orderPayload = { cart_id: cartId };
  if (reservationId) orderPayload.reservation_id = reservationId;
  const idemKey = `idem-${cartId}`;
  const orderHeaders = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idemKey,
  };
  if (etag) orderHeaders['If-Match'] = etag;
  res = http.post(`${BASE}/v2/orders`, JSON.stringify(orderPayload), { headers: orderHeaders, redirects: 0 });
  check(res, { 'order 201 accepted': (r) => r.status === 201 });
  body = jsonBody(res);
  check(body, { 'order accepted true': (b) => b && b.accepted === true });
  if (body && body.csrf) csrf = body.csrf;

  // 9. business work
  res = http.post(`${BASE}/v2/work`, '{}', {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  check(res, { 'work ok': (r) => r.status === 200 });
  body = jsonBody(res);
  check(body, { 'work ok true': (b) => b && b.ok === true });

  // per-account delay
  sleep(acct.delay);
}
