import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Rate } from 'k6/metrics';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const committedOrders = new Counter('committed_orders');
const businessFailure = new Rate('business_failure');

export const options = {
  scenarios: {
    journey: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '38s',
      gracefulStop: '5s',
    },
  },
  thresholds: {
    business_failure: ['rate<=0.01'],
  },
};

function parseCsrfFromForm(body) {
  const m = body.match(/<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i);
  return m ? m[1] : null;
}

function getHeader(res, name) {
  const h = res.headers[name] || res.headers[name.toLowerCase()];
  return h || null;
}

function pickProduct(catalog) {
  const products = (catalog && catalog.data && catalog.data.products) || [];
  for (const p of products) {
    const variants = p.variants || [];
    for (const v of variants) {
      if (v.in_stock) return { product: p.id, variant: v.id };
    }
  }
  return null;
}

function doLogin(vu) {
  const formRes = http.get(`${BASE}/v2/login-form`, { redirects: 0 });
  const formCsrf = parseCsrfFromForm(formRes.body || '');
  if (!formCsrf) return null;

  const loginRes = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username: `bench-${vu}`, password: 'bench', csrf: formCsrf }),
    { headers: { 'Content-Type': 'application/json' }, redirects: 0 }
  );

  let csrf = null;
  try {
    const j = loginRes.json();
    csrf = j && j.csrf;
  } catch (e) { /* ignore */ }

  if (loginRes.status === 302) {
    const loc = getHeader(loginRes, 'Location');
    if (loc) {
      const followRes = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { redirects: 0 });
      try {
        const j = followRes.json();
        if (j && j.csrf) csrf = j.csrf;
      } catch (e) { /* ignore */ }
    }
  }
  return csrf;
}

function doChallenge(csrf) {
  const formRes = http.get(`${BASE}/v2/challenge-form`, { redirects: 0 });
  const body = formRes.body || '';
  const actionMatch = body.match(/action=["']([^"']*\/v2\/challenges\/[^"']+)["']/i);
  const challengeMatch = body.match(/<input(?=[^>]*\bname=["']challenge["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i);
  if (!actionMatch || !challengeMatch) return { grant: null, csrf };
  const action = actionMatch[1];
  const challenge = challengeMatch[1];
  const url = action.startsWith('http') ? action : `${BASE}${action}`;
  const postRes = http.post(url, JSON.stringify({ challenge }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  let newCsrf = csrf;
  let grant = null;
  if (postRes.status === 302) {
    const loc = getHeader(postRes, 'Location');
    if (loc) {
      const followRes = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { redirects: 0 });
      try {
        const j = followRes.json();
        if (j && j.csrf) newCsrf = j.csrf;
        if (j && j.grant_id) grant = j.grant_id;
      } catch (e) { /* ignore */ }
    }
  }
  return { grant, csrf: newCsrf };
}

function renewSession(csrf) {
  const res = http.post(`${BASE}/v2/session/renew`, '{}', {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  try {
    const j = res.json();
    if (j && j.csrf) return j.csrf;
  } catch (e) { /* ignore */ }
  return csrf;
}

function recoverCart(cartId, csrf) {
  const res = http.post(`${BASE}/v2/carts/${cartId}/recover`, '{}', {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  try {
    const j = res.json();
    if (j && j.csrf) return j.csrf;
  } catch (e) { /* ignore */ }
  return csrf;
}

function isExpired(res) {
  try {
    const j = res.json();
    return j && (j.error === 'expired' || j.error === 'session');
  } catch (e) {
    return false;
  }
}

function isDenied(res) {
  try {
    const j = res.json();
    return j && j.error === 'denied';
  } catch (e) {
    return false;
  }
}

function pollReservation(statusUrl, csrf) {
  const url = statusUrl.startsWith('http') ? statusUrl : `${BASE}${statusUrl}`;
  for (let i = 0; i < 5; i++) {
    sleep(0.06);
    const res = http.get(url, { headers: { 'X-CSRF-Token': csrf }, redirects: 0 });
    if (res.status === 401 && isExpired(res)) {
      csrf = renewSession(csrf);
      continue;
    }
    try {
      const j = res.json();
      if (j && j.status === 'ready' && j.reservation_id) {
        return { reservation_id: j.reservation_id, csrf: j.csrf || csrf };
      }
      if (j && (j.status === 'failed')) return { reservation_id: null, csrf: j.csrf || csrf };
    } catch (e) { /* ignore */ }
  }
  return { reservation_id: null, csrf };
}

export default function () {
  const vu = __VU;
  let csrf = doLogin(vu);
  if (!csrf) {
    businessFailure.add(true);
    return;
  }

  // Catalog
  let catalogRes = http.get(`${BASE}/v2/catalog`, { headers: { 'X-CSRF-Token': csrf }, redirects: 0 });
  if (catalogRes.status === 401 && isExpired(catalogRes)) {
    csrf = renewSession(csrf);
    catalogRes = http.get(`${BASE}/v2/catalog`, { headers: { 'X-CSRF-Token': csrf }, redirects: 0 });
  }
  let catalog = null;
  try { catalog = catalogRes.json(); } catch (e) { /* ignore */ }
  let pick = pickProduct(catalog);
  if (!pick) {
    // try paged catalog
    const pageRes = http.get(`${BASE}/v2/catalog/page`, { headers: { 'X-CSRF-Token': csrf }, redirects: 0 });
    try {
      const pj = pageRes.json();
      if (pj && pj.product) {
        const variants = pj.product.variants || [];
        for (const v of variants) {
          if (v.in_stock) { pick = { product: pj.product.id, variant: v.id }; break; }
        }
      }
    } catch (e) { /* ignore */ }
  }
  if (!pick) {
    businessFailure.add(true);
    return;
  }

  // Challenge for grant
  const ch = doChallenge(csrf);
  csrf = ch.csrf;
  const grant = ch.grant;

  // Create cart
  const cartBody = { product_id: pick.product, variant_id: pick.variant };
  if (grant) cartBody.grant_id = grant;
  let cartRes = http.post(`${BASE}/v2/carts`, JSON.stringify(cartBody), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
