  });
  if (cartRes.status === 401 && isExpired(cartRes)) {
    csrf = renewSession(csrf);
    cartRes = http.post(`${BASE}/v2/carts`, JSON.stringify(cartBody), {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
      redirects: 0,
    });
  }
  let cartId = null;
  try {
    const j = cartRes.json();
    if (j && j.id) cartId = j.id;
    if (j && j.csrf) csrf = j.csrf;
  } catch (e) { /* ignore */ }
  if (!cartId) {
    businessFailure.add(true);
    return;
  }
  let etag = getHeader(cartRes, 'ETag');

  // GET cart for ETag
  let getCart = http.get(`${BASE}/v2/carts/${cartId}`, { headers: { 'X-CSRF-Token': csrf }, redirects: 0 });
  if (getCart.status === 401 && isExpired(getCart)) {
    csrf = renewSession(csrf);
    csrf = recoverCart(cartId, csrf);
    getCart = http.get(`${BASE}/v2/carts/${cartId}`, { headers: { 'X-CSRF-Token': csrf }, redirects: 0 });
  }
  const e2 = getHeader(getCart, 'ETag');
  if (e2) etag = e2;

  // PATCH quantity
  const patchPayload = JSON.stringify({ quantity: 2 });
