    const e3 = getHeader(reread, 'ETag');
    if (e3) etag = e3;
    patchRes = http.patch(`${BASE}/v2/carts/${cartId}`, patchPayload, {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf, 'If-Match': etag || '' },
      redirects: 0,
    });
  }
  if (patchRes.status === 401 && isExpired(patchRes)) {
    csrf = renewSession(csrf);
    csrf = recoverCart(cartId, csrf);
    patchRes = http.patch(`${BASE}/v2/carts/${cartId}`, patchPayload, {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf, 'If-Match': etag || '' },
      redirects: 0,
    });
  }
  try {
    const j = patchRes.json();
    if (j && j.csrf) csrf = j.csrf;
  } catch (e) { /* ignore */ }
  const e4 = getHeader(patchRes, 'ETag');
  if (e4) etag = e4;

  // Reservation
  let resRes = http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
