  const orderBody = { cart_id: cartId, reservation_id: reservationId };
  const idemKey = `idem-${cartId}`;
  let orderRes = http.post(`${BASE}/v2/orders`, JSON.stringify(orderBody), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
