      const j = orderRes.json();
      if (j && j.accepted === true) committed = true;
    } catch (e) { /* ignore */ }
  }
  if (committed) {
    committedOrders.add(1);
    businessFailure.add(false);
  } else {
    if (orderRes.status === 401 && isDenied(orderRes)) {
      businessFailure.add(true);
    } else {
      businessFailure.add(true);
    }
  }

  check(orderRes, {
    'order committed': () => committed,
  });
}
