import http from 'k6/http';
import { check, group, fail } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

// ---- custom metrics ----
const businessFailure = new Rate('business_failure');
const unexpectedFailures = new Counter('unexpected_failures');
const businessResponses = new Counter('business_responses');
const ordersCommitted = new Counter('orders_committed');
const cartsCreated = new Counter('carts_created');
const journeyDuration = new Trend('journey_duration');

// ---- thresholds (contract scope) ----
export const options = {
  scenarios: {
    journey: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '2m',
    },
  },
  thresholds: {
    // transaction-level error limits
    'business_failure': ['rate<0.05'],
    'unexpected_failures': ['count<1'],
    'orders_committed': ['count>=4'],
    'carts_created': ['count==4'],
    'http_req_failed': ['rate<0.10'],
    'checks': ['rate>0.95'],
  },
};

// ---- helpers ----
function parseCsrfFromForm(body) {
  // input[name=csrf] with value, tolerant of attribute order / quotes
  const re = /<input\b[^>]*\bname=["']csrf["'][^>]*\bvalue=["']([^"']+)["'][^>]*>/i;
  let m = body.match(re);
  if (m) return m[1];
  const re2 = /<input\b[^>]*\bvalue=["']([^"']+)["'][^>]*\bname=["']csrf["'][^>]*>/i;
  m = body.match(re2);
  return m ? m[1] : null;
}

function getHeader(res, name) {
  const h = res.headers[name] || res.headers[name.toLowerCase()];
  return h || null;
}

function isExpired(res) {
  try {
    const b = res.json();
    return b && b.error === 'expired';
  } catch (e) { return false; }
}
function isSessionRevoked(res) {
  try {
    const b = res.json();
    return b && b.error === 'session';
  } catch (e) { return false; }
}
function isDenied(res) {
  try {
    const b = res.json();
    return b && b.error === 'denied';
  } catch (e) { return false; }
}

function recordBusiness(res, expected) {
  businessResponses.add(1);
  if (expected) return;
  // unexpected failure (exclude expected expiry / scheduled 429)
  if (res.status === 429) return;
  if (res.status === 401 && (isExpired(res) || isSessionRevoked(res))) return;
  unexpectedFailures.add(1);
  businessFailure.add(true);
}

function recordBusinessOk() {
  businessResponses.add(1);
  businessFailure.add(false);
}

// ---- journey ----
export default function () {
  const start = Date.now();
  const vu = __VU;
  const username = `bench-${vu}`;
  const password = 'bench';

  let csrf = null;
  let sessionCookie = null;
  let cartId = null;
  let etag = null;
  let grantId = null;
  let productId = null;
  let variantId = null;
  let orderCommitted = false;

  const jar = http.cookieJar();

  // 1. login form
  let res = http.get(`${BASE}/v2/login-form`, { redirects: 0 });
  check(res, { 'login-form 200': (r) => r.status === 200 });
  if (res.status !== 200) { recordBusiness(res, false); fail('login-form failed'); }
  csrf = parseCsrfFromForm(res.body);
  check(res, { 'login-form csrf extracted': () => !!csrf });
  if (!csrf) { recordBusiness(res, false); fail('no csrf'); }

  // 2. login
  res = http.post(`${BASE}/v2/login`, JSON.stringify({ username, password, csrf }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
  });
  if (res.status === 302) {
    const loc = getHeader(res, 'Location');
    check(res, { 'login redirect has Location': () => !!loc });
    if (loc) {
      const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { redirects: 0 });
      check(follow, { 'login follow 200': (r) => r.status === 200 });
      try {
        const b = follow.json();
        if (b && b.csrf) csrf = b.csrf;
      } catch (e) {}
    }
  } else {
    check(res, { 'login 200/302': (r) => r.status === 200 || r.status === 302 });
    try {
      const b = res.json();
      if (b && b.csrf) csrf = b.csrf;
    } catch (e) {}
  }
  check(res, { 'login csrf present': () => !!csrf });
  if (!csrf) { recordBusiness(res, false); fail('login no csrf'); }

  // 3. catalog
  res = http.get(`${BASE}/v2/catalog`, { redirects: 0 });
  check(res, { 'catalog 200': (r) => r.status === 200 });
  if (res.status !== 200) { recordBusiness(res, false); fail('catalog failed'); }
  try {
    const b = res.json();
    const products = (b && b.data && b.data.products) || [];
    for (const p of products) {
      const vs = p.variants || [];
      const v = vs.find((x) => x.in_stock);
      if (v) { productId = p.id; variantId = v.id; break; }
    }
  } catch (e) {}
  check(res, { 'catalog product+variant found': () => !!productId && !!variantId });
  if (!productId || !variantId) { recordBusiness(res, false); fail('no product'); }

  // 4. challenge (grant)
  res = http.get(`${BASE}/v2/challenge-form`, { redirects: 0 });
  check(res, { 'challenge-form 200': (r) => r.status === 200 });
  if (res.status === 200) {
    const actionMatch = res.body.match(/action=["']([^"']*\/v2\/challenges\/[^"']+)["']/i);
    const challengeMatch = res.body.match(/<input\b[^>]*\bname=["']challenge["'][^>]*\bvalue=["']([^"']+)["'][^>]*>/i);
    if (actionMatch && challengeMatch) {
      const action = actionMatch[1];
      const challenge = challengeMatch[1];
      const url = action.startsWith('http') ? action : `${BASE}${action}`;
      let cres = http.post(url, JSON.stringify({ challenge }), {
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
        redirects: 0,
      });
      if (cres.status === 302) {
        const loc = getHeader(cres, 'Location');
        if (loc) {
          const gres = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { redirects: 0 });
          try {
            const gb = gres.json();
            if (gb && gb.grant_id) grantId = gb.grant_id;
            if (gb && gb.csrf) csrf = gb.csrf;
          } catch (e) {}
        }
      }
    }
  }
  check(res, { 'grant obtained': () => !!grantId });

  // 5. create cart
  const cartBody = { product_id: productId, variant_id: variantId };
  if (grantId) cartBody.grant_id = grantId;
  res = http.post(`${BASE}/v2/carts`, JSON.stringify(cartBody), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  check(res, { 'cart 201': (r) => r.status === 201 });
  if (res.status !== 201) { recordBusiness(res, false); fail('cart create failed'); }
  try {
    const b = res.json();
    cartId = b.id;
    if (b.csrf) csrf = b.csrf;
  } catch (e) {}
  etag = getHeader(res, 'ETag');
  check(res, { 'cart id + etag': () => !!cartId && !!etag });
  if (!cartId) { recordBusiness(res, false); fail('no cart id'); }
  cartsCreated.add(1);

  // 6. patch quantity with If-Match, retry once on 412
  const patchBody = JSON.stringify({ quantity: 2 });
  let patched = false;
  for (let attempt = 0; attempt < 2 && !patched; attempt++) {
    res = http.patch(`${BASE}/v2/carts/${cartId}`, patchBody, {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
        'If-Match': etag || '',
      },
      redirects: 0,
    });
    if (res.status === 412) {
      // re-read
      const rres = http.get(`${BASE}/v2/carts/${cartId}`, { redirects: 0 });
      const newEtag = getHeader(rres, 'ETag');
      if (newEtag) etag = newEtag;
      continue;
    }
    if (res.status === 200 || res.status === 204) {
      patched = true;
      const newEtag = getHeader(res, 'ETag');
      if (newEtag) etag = newEtag;
      try { const b = res.json(); if (b && b.csrf) csrf = b.csrf; } catch (e) {}
    } else {
      break;
    }
  }
  check(res, { 'cart patched': () => patched });
  if (!patched) { recordBusiness(res, false); fail('patch failed'); }

  // 7. reservation
  let reservationId = null;
  res = http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  check(res, { 'reservation 202': (r) => r.status === 202 });
  if (res.status === 202) {
    let statusUrl = null;
    try { const b = res.json(); statusUrl = b.status_url; if (b.csrf) csrf = b.csrf; } catch (e) {}
    if (statusUrl) {
      const url = statusUrl.startsWith('http') ? statusUrl : `${BASE}${statusUrl}`;
      for (let i = 0; i < 5; i++) {
        if (i > 0) { /* sleep 50ms */ }
        const sres = http.get(url, { redirects: 0 });
        try {
          const sb = sres.json();
          if (sb.status === 'ready' && sb.reservation_id) { reservationId = sb.reservation_id; break; }
          if (sb.status === 'failed') break;
        } catch (e) {}
        // busy-wait ~50ms
        const t0 = Date.now();
        while (Date.now() - t0 < 50) {}
      }
    }
  }
  check(res, { 'reservation ready': () => !!reservationId });

  // 8. order
  const orderBody = { cart_id: cartId };
  if (reservationId) orderBody.reservation_id = reservationId;
  const idemKey = `idem-${cartId}`;
  res = http.post(`${BASE}/v2/orders`, JSON.stringify(orderBody), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'Idempotency-Key': idemKey,
      'If-Match': etag || '',
    },
    redirects: 0,
  });
  let accepted = false;
  try {
    const b = res.json();
    accepted = !!(b && b.accepted === true);
    if (b && b.csrf) csrf = b.csrf;
  } catch (e) {}
  check(res, { 'order accepted': () => accepted });
  if (accepted) {
    orderCommitted = true;
    ordersCommitted.add(1);
    recordBusinessOk();
  } else {
    // business failure (200 accepted:false) or error
    recordBusiness(res, false);
  }

  journeyDuration.add(Date.now() - start);
}
