import http from 'k6/http';
import { check, group } from 'k6';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    journey: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '2m',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

function jar() {
  return http.cookieJar();
}

function parseCsrfFromForm(body) {
  if (!body) return null;
  const re = /<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i;
  const m = body.match(re);
  return m ? m[1] : null;
}

function getHeader(res, name) {
  const h = res.headers[name] || res.headers[name.toLowerCase()];
  return h || null;
}

function isExpired(res) {
  if (res.status !== 401) return false;
  try {
    const b = res.json();
    return b && (b.error === 'expired' || b.error === 'session');
  } catch (e) {
    return false;
  }
}

function isDenied(res) {
  if (res.status !== 401) return false;
  try {
    const b = res.json();
    return b && b.error === 'denied';
  } catch (e) {
    return false;
  }
}

function pickProduct(catalogBody) {
  try {
    const b = JSON.parse(catalogBody);
    const products = (b && b.data && b.data.products) || [];
    for (const p of products) {
      const vs = p.variants || [];
      for (const v of vs) {
        if (v.in_stock) return { product: p.id, variant: v.id };
      }
    }
  } catch (e) {}
  return null;
}

function loginFlow(jarRef, username) {
  const formRes = http.get(`${BASE}/v2/login-form`, { jar: jarRef, redirects: 0 });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const formCsrf = parseCsrfFromForm(formRes.body);
  check(formCsrf, { 'login-form csrf': (v) => !!v });

  const loginRes = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username, password: 'bench', csrf: formCsrf }),
    { jar: jarRef, redirects: 0, headers: { 'Content-Type': 'application/json' } }
  );
  check(loginRes, { 'login ok': (r) => r.status === 200 || r.status === 302 });

  let csrf = null;
  if (loginRes.status === 302) {
    const loc = getHeader(loginRes, 'Location');
    check(loc, { 'login redirect location': (v) => !!v });
    if (loc) {
      const followRes = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, {
        jar: jarRef,
        redirects: 0,
      });
      check(followRes, { 'login follow 200': (r) => r.status === 200 });
      try {
        const b = followRes.json();
        csrf = b && b.csrf;
      } catch (e) {}
    }
  } else {
    try {
      const b = loginRes.json();
      csrf = b && b.csrf;
    } catch (e) {}
  }
  check(csrf, { 'login csrf': (v) => !!v });
  return csrf;
}

function renewSession(jarRef, csrf) {
  const res = http.post(`${BASE}/v2/session/renew`, '{}', {
    jar: jarRef,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf || '' },
  });
  let newCsrf = csrf;
  if (res.status === 200) {
    try {
      const b = res.json();
      if (b && b.csrf) newCsrf = b.csrf;
    } catch (e) {}
  }
  return { ok: res.status === 200, csrf: newCsrf };
}

function recoverCart(jarRef, csrf, cartId) {
  const res = http.post(`${BASE}/v2/carts/${cartId}/recover`, '{}', {
    jar: jarRef,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf || '' },
  });
  let newCsrf = csrf;
  if (res.status === 200) {
    try {
      const b = res.json();
      if (b && b.csrf) newCsrf = b.csrf;
    } catch (e) {}
  }
  return { ok: res.status === 200, csrf: newCsrf };
}

function withExpiryRetry(jarRef, csrfRef, cartId, doFn) {
  // doFn(csrf) -> { res, csrf }
  let out = doFn(csrfRef.value);
  if (isExpired(out.res)) {
    // bounded: one recovery attempt
    const rn = renewSession(jarRef, out.csrf || csrfRef.value);
    let csrf = rn.csrf;
    if (cartId) {
      const rc = recoverCart(jarRef, csrf, cartId);
      if (rc.csrf) csrf = rc.csrf;
    }
    csrfRef.value = csrf;
    out = doFn(csrf);
  }
  return out;
}

export default function () {
  const jarRef = jar();
  const username = `bench-${__VU}`;
  const csrfRef = { value: null };

  group('login', () => {
    csrfRef.value = loginFlow(jarRef, username);
  });

  group('catalog', () => {
    const res = http.get(`${BASE}/v2/catalog`, { jar: jarRef, redirects: 0 });
    check(res, { 'catalog 200': (r) => r.status === 200 });
    const pick = pickProduct(res.body);
    check(pick, { 'catalog pick': (v) => !!v });
    if (!pick) return;

    // challenge flow
    let grant = null;
    const chForm = http.get(`${BASE}/v2/challenge-form`, { jar: jarRef, redirects: 0 });
    check(chForm, { 'challenge-form 200': (r) => r.status === 200 });
    const actionMatch = chForm.body && chForm.body.match(/action=["']([^"']+)["']/i);
    const challengeMatch = chForm.body && chForm.body.match(/name=["']challenge["'][^>]*value=["']([^"']+)["']/i);
    const action = actionMatch ? actionMatch[1] : null;
    const challenge = challengeMatch ? challengeMatch[1] : null;
    check(action && challenge, { 'challenge parsed': (v) => !!v });

    if (action && challenge) {
      const chPost = http.post(
        action.startsWith('http') ? action : `${BASE}${action}`,
        JSON.stringify({ challenge }),
        {
          jar: jarRef,
          redirects: 0,
          headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrfRef.value || '' },
        }
      );
      check(chPost, { 'challenge post 302': (r) => r.status === 302 });
      const loc = getHeader(chPost, 'Location');
      if (loc) {
        const chGet = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, {
          jar: jarRef,
          redirects: 0,
        });
        check(chGet, { 'challenge get 200': (r) => r.status === 200 });
        try {
          const b = chGet.json();
          if (b && b.grant_id) grant = b.grant_id;
          if (b && b.csrf) csrfRef.value = b.csrf;
        } catch (e) {}
      }
    }

    // create cart
    const cartBody = { product_id: pick.product, variant_id: pick.variant };
    if (grant) cartBody.grant_id = grant;

    let cartId = null;
    let etag = null;

    const createRes = withExpiryRetry(jarRef, csrfRef, null, (csrf) => {
      const r = http.post(`${BASE}/v2/carts`, JSON.stringify(cartBody), {
        jar: jarRef,
        redirects: 0,
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf || '' },
      });
      let c = csrf;
      if (r.status === 201) {
        try {
          const b = r.json();
          if (b && b.csrf) c = b.csrf;
        } catch (e) {}
      }
      return { res: r, csrf: c };
    });
    csrfRef.value = createRes.csrf;
    check(createRes.res, { 'cart created 201': (r) => r.status === 201 });
    if (createRes.res.status === 201) {
      try {
        const b = createRes.res.json();
        cartId = b && b.id;
      } catch (e) {}
      etag = getHeader(createRes.res, 'ETag');
    }
    check(cartId, { 'cart id': (v) => !!v });
    if (!cartId) return;

    // PATCH quantity with 412 retry
    const patchPayload = JSON.stringify({ quantity: 2 });
    let patchRes = http.patch(`${BASE}/v2/carts/${cartId}`, patchPayload, {
      jar: jarRef,
      redirects: 0,
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrfRef.value || '',
        'If-Match': etag || '',
      },
    });
    if (patchRes.status === 412) {
      const reRead = http.get(`${BASE}/v2/carts/${cartId}`, { jar: jarRef, redirects: 0 });
      const newEtag = getHeader(reRead, 'ETag');
      if (newEtag) etag = newEtag;
      patchRes = http.patch(`${BASE}/v2/carts/${cartId}`, patchPayload, {
        jar: jarRef,
        redirects: 0,
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': csrfRef.value || '',
          'If-Match': etag || '',
        },
      });
    }
    check(patchRes, { 'patch ok': (r) => r.status === 200 || r.status === 204 });
    const patchEtag = getHeader(patchRes, 'ETag');
    if (patchEtag) etag = patchEtag;
    try {
      const b = patchRes.json();
      if (b && b.csrf) csrfRef.value = b.csrf;
    } catch (e) {}

    // reservation
    let reservationId = null;
    const resvRes = withExpiryRetry(jarRef, csrfRef, cartId, (csrf) => {
      const r = http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
        jar: jarRef,
        redirects: 0,
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf || '' },
      });
      let c = csrf;
      if (r.status === 202) {
        try {
          const b = r.json();
          if (b && b.csrf) c = b.csrf;
        } catch (e) {}
      }
      return { res: r, csrf: c };
    });
    csrfRef.value = resvRes.csrf;
    check(resvRes.res, { 'reservation 202': (r) => r.status === 202 });

    let statusUrl = null;
    if (resvRes.res.status === 202) {
      try {
        const b = resvRes.res.json();
        statusUrl = b && b.status_url;
      } catch (e) {}
    }

    if (statusUrl) {
      for (let i = 0; i < 5; i++) {
        const pollRes = http.get(statusUrl.startsWith('http') ? statusUrl : `${BASE}${statusUrl}`, {
          jar: jarRef,
          redirects: 0,
        });
        let status = null;
        try {
          const b = pollRes.json();
          status = b && b.status;
          if (b && b.csrf) csrfRef.value = b.csrf;
          if (status === 'ready' && b.reservation_id) reservationId = b.reservation_id;
        } catch (e) {}
        if (status === 'ready' || status === 'failed') break;
        // at least 50ms apart
        const start = Date.now();
        while (Date.now() - start < 60) { /* busy wait */ }
      }
    }
    check(reservationId, { 'reservation ready': (v) => !!v });

    // order
    const orderBody = { cart_id: cartId };
    if (reservationId) orderBody.reservation_id = reservationId;
    const idemKey = `idem-${cartId}`;

    const orderRes = withExpiryRetry(jarRef, csrfRef, cartId, (csrf) => {
      const headers = {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf || '',
        'Idempotency-Key': idemKey,
      };
      if (etag) headers['If-Match'] = etag;
      const r = http.post(`${BASE}/v2/orders`, JSON.stringify(orderBody), {
        jar: jarRef,
        redirects: 0,
        headers,
      });
      let c = csrf;
      if (r.status === 201) {
        try {
          const b = r.json();
          if (b && b.csrf) c = b.csrf;
        } catch (e) {}
      }
      return { res: r, csrf: c };
    });
    csrfRef.value = orderRes.csrf;

    check(orderRes.res, {
      'order 201': (r) => r.status === 201,
      'order accepted true': (r) => {
        try {
          const b = r.json();
          return b && b.accepted === true;
        } catch (e) {
          return false;
        }
      },
    });
  });
}
