import http from 'k6/http';
import { check } from 'k6';
import { Counter, Rate } from 'k6/metrics';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const workStarts = new Counter('work_starts');
const workOk = new Counter('work_ok');
const workFail = new Counter('work_fail');
const bizFail = new Rate('business_failure');

export const options = {
  scenarios: {
    work: {
      executor: 'constant-arrival-rate',
      rate: 5,
      timeUnit: '1s',
      duration: '40s',
      preAllocatedVUs: 4,
      maxVUs: 32,
      exec: 'workFlow',
    },
  },
  thresholds: {
    'business_failure': ['rate<0.01'],
  },
  discardResponseBodies: false,
};

function parseCsrf(html) {
  // input[name=csrf] with possible attribute variants
  const m = html.match(/<input[^>]*name=["']?csrf["']?[^>]*value=["']([^"']+)["']/i)
    || html.match(/<input[^>]*value=["']([^"']+)["'][^>]*name=["']?csrf["']?/i);
  return m ? m[1] : null;
}

function getCookie(jar, name) {
  const cookies = jar.cookiesForURL(BASE);
  const v = cookies[name];
  return Array.isArray(v) ? v[0] : v;
}

function login() {
  const jar = http.cookieJar();
  jar.clear(BASE);
  const formRes = http.get(`${BASE}/v2/login-form`, { redirects: 0 });
  if (formRes.status !== 200) return null;
  const csrf = parseCsrf(formRes.body);
  if (!csrf) return null;
  const loginRes = http.post(`${BASE}/v2/login`, JSON.stringify({
    username: 'bench-1', password: 'bench', csrf,
  }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
  });
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'];
    if (loc) http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { redirects: 0 });
  }
  if (loginRes.status >= 400) return null;
  let body = {};
  try { body = JSON.parse(loginRes.body); } catch (e) {}
  const token = body.csrf || csrf;
  return { csrf: token };
}

function doWork(session) {
  const res = http.post(`${BASE}/v2/work`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': session.csrf,
    },
    redirects: 0,
    tags: { op: 'work' },
  });
  workStarts.add(1);
  if (res.status === 429) {
    const ra = res.headers['Retry-After'];
    const wait = ra ? parseFloat(ra) * 1000 : 1000;
    return { retry: true, wait };
  }
  if (res.status === 401) {
    let err = '';
    try { err = JSON.parse(res.body).error || ''; } catch (e) {}
    if (err === 'expired' || err === 'session') {
      return { renew: true };
    }
    bizFail.add(true);
    workFail.add(1);
    return { fail: true };
  }
  if (res.status >= 400) {
    bizFail.add(true);
    workFail.add(1);
    return { fail: true };
  }
  let ok = false;
  try { ok = JSON.parse(res.body).ok === true; } catch (e) {}
  if (ok) {
    workOk.add(1);
    bizFail.add(false);
    return { ok: true };
  }
  bizFail.add(true);
  workFail.add(1);
  return { fail: true };
}

function renew(session) {
  const res = http.post(`${BASE}/v2/session/renew`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': session.csrf,
    },
    redirects: 0,
  });
  if (res.status >= 400) return null;
  let body = {};
  try { body = JSON.parse(res.body); } catch (e) {}
  if (body.csrf) session.csrf = body.csrf;
  return session;
}

export function workFlow() {
  let session = login();
  if (!session) {
    bizFail.add(true);
    return;
  }
  let retries = 0;
  let renewed = false;
  while (retries <= 4) {
    const r = doWork(session);
    if (r.ok) return;
    if (r.retry) {
      retries++;
      if (retries > 4) return;
      // sleep handled by arrival-rate pacing; do a short busy wait via http.batch? use sleep
      // k6 sleep is allowed
      // eslint-disable-next-line no-undef
      // use global sleep
      // (imported below)
      sleepMs(r.wait);
      continue;
    }
    if (r.renew && !renewed) {
      renewed = true;
      const s2 = renew(session);
      if (!s2) {
        // fresh login
        const s3 = login();
        if (!s3) { bizFail.add(true); return; }
        session = s3;
      }
      continue;
    }
    return;
  }
}

function sleepMs(ms) {
  const end = Date.now() + ms;
  while (Date.now() < end) { /* spin */ }
}
