import http from 'k6/http';
import { check } from 'k6';
import { Trend, Counter } from 'k6/metrics';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const workLatency = new Trend('work_latency', true);
const workOk = new Counter('work_ok');
const workErr = new Counter('work_err');
const workSched = new Counter('work_sched');

export const options = {
  scenarios: {
    phased: {
      executor: 'ramping-arrival-rate',
      startRate: 5,
      timeUnit: '1s',
      preAllocatedVUs: 32,
      maxVUs: 32,
      stages: [
        { target: 5, duration: '10s' },
        { target: 15, duration: '10s' },
        { target: 5, duration: '10s' },
      ],
      gracefulStop: '5s',
    },
  },
  thresholds: {
    work_err: ['count<100'],
  },
  discardResponseBodies: false,
};

function parseCsrf(html) {
  // input[name=csrf] with possible attribute variants
  const m = html.match(/<input[^>]*name=["']?csrf["']?[^>]*>/i);
  if (!m) return null;
  const tag = m[0];
  const v = tag.match(/value=["']([^"']*)["']/i);
  return v ? v[1] : null;
}

function login() {
  const jar = http.cookieJar();
  const formRes = http.get(`${BASE}/v2/login-form`, { redirects: 0 });
  const csrf = parseCsrf(formRes.body || '');
  if (!csrf) return null;
  const user = `bench-${1 + (__VU % 16)}`;
  const res = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username: user, password: 'bench', csrf }),
    { headers: { 'Content-Type': 'application/json' }, redirects: 0 }
  );
  if (res.status === 302) {
    const loc = res.headers['Location'];
    if (loc) http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { redirects: 0 });
  }
  let body = {};
  try { body = JSON.parse(res.body || '{}'); } catch (e) {}
  return { csrf: body.csrf || csrf, user: body.user || user };
}

function doWork(session) {
  let csrf = session.csrf;
  let attempts = 0;
  while (attempts < 5) {
    attempts++;
    const res = http.post(`${BASE}/v2/work`, '{}', {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
      },
      redirects: 0,
      tags: { op: 'work' },
    });
    if (res.status === 429) {
      workSched.add(1);
      const ra = parseFloat(res.headers['Retry-After'] || '1');
      const wait = isNaN(ra) ? 1 : ra;
      if (attempts >= 4) return false;
      // sleep via busy wait not allowed; use http.get to /v2/health? forbidden.
      // Use a short sleep through k6 sleep
      // eslint-disable-next-line no-undef
      sleep(wait);
      continue;
    }
    if (res.status === 401) {
      // try renew
      const rn = http.post(`${BASE}/v2/session/renew`, '{}', {
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
        redirects: 0,
      });
      if (rn.status < 400) {
        try {
          const b = JSON.parse(rn.body || '{}');
          if (b.csrf) csrf = b.csrf;
        } catch (e) {}
        continue;
      }
      // re-login
      const s = login();
      if (!s) return false;
      csrf = s.csrf;
      continue;
    }
    if (res.status >= 400) {
      workErr.add(1);
      return false;
    }
    workOk.add(1);
    workLatency.add(res.timings.duration);
    try {
      const b = JSON.parse(res.body || '{}');
      if (b.csrf) csrf = b.csrf;
    } catch (e) {}
    session.csrf = csrf;
    return true;
  }
  return false;
}

// k6 sleep import
import { sleep } from 'k6';

export default function () {
  const session = login();
  if (!session) {
    workErr.add(1);
    return;
  }
  doWork(session);
}
