import http from 'k6/http';
import { check } from 'k6';
import { Counter, Rate } from 'k6/metrics';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const workOk = new Counter('work_ok');
const work429 = new Counter('work_429');
const workErr = new Counter('work_err');
const bizFail = new Rate('business_failure');

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '60s',
    },
  },
  thresholds: {
    'business_failure': ['rate<0.01'],
  },
  summaryTrendStats: ['avg', 'min', 'med', 'max', 'p(90)', 'p(95)'],
};

function parseCsrf(html) {
  // input[name=csrf] with possible attribute variants / decoys
  const re = /<input\b[^>]*\bname\s*=\s*["']?csrf["']?[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  // fallback: value before name
  const re2 = /<input\b[^>]*\bvalue\s*=\s*["']([^"']*)["'][^>]*\bname\s*=\s*["']?csrf["']?/gi;
  while ((m = re2.exec(html)) !== null) return m[1];
  return null;
}

function getCookie(jar, name) {
  const cookies = jar.cookiesForURL(BASE);
  const arr = cookies[name];
  return arr && arr.length ? arr[0] : null;
}

function login(jar) {
  const user = 'bench-' + (1 + Math.floor(Math.random() * 16));
  const formRes = http.get(BASE + '/v2/login-form', { jar, redirects: 0 });
  if (formRes.status !== 200) return null;
  const csrf = parseCsrf(formRes.body);
  if (!csrf) return null;
  const loginRes = http.post(
    BASE + '/v2/login',
    JSON.stringify({ username: user, password: 'bench', csrf }),
    { jar, redirects: 0, headers: { 'Content-Type': 'application/json' } }
  );
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'];
    if (loc) {
      const follow = http.get(loc.startsWith('http') ? loc : BASE + loc, { jar, redirects: 0 });
      if (follow.status >= 400) return null;
    }
  } else if (loginRes.status >= 400) {
    return null;
  }
  let body = null;
  try { body = loginRes.json(); } catch (e) { body = null; }
  let token = body && body.csrf ? body.csrf : csrf;
  return { user, csrf: token };
}

function renew(jar, csrf) {
  const r = http.post(BASE + '/v2/session/renew', '{}', {
    jar,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  if (r.status >= 400) return null;
  let body = null;
  try { body = r.json(); } catch (e) { body = null; }
  return body && body.csrf ? body.csrf : csrf;
}

function doWork(jar, csrf) {
  // returns {ok, csrf}
  let curCsrf = csrf;
  let retries = 0;
  let renewed = false;
  while (retries <= 4) {
    const res = http.post(BASE + '/v2/work', '{}', {
      jar,
      redirects: 0,
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': curCsrf },
      tags: { name: 'work' },
    });
    if (res.status === 429) {
      work429.add(1);
      const ra = res.headers['Retry-After'];
      let wait = 1;
      if (ra) {
        const n = parseFloat(ra);
        if (!isNaN(n)) wait = n;
      }
      if (wait > 5) wait = 5;
      // sleep in ms
      const start = Date.now();
      while (Date.now() - start < wait * 1000) {
        // busy-ish sleep via http? use sleep
        break;
      }
      // use k6 sleep
      // eslint-disable-next-line no-undef
      try { require('k6').sleep(wait); } catch (e) {}
      retries++;
      continue;
    }
    if (res.status === 401) {
      let err = null;
      try { err = res.json().error; } catch (e) {}
      if (err === 'expired' && !renewed) {
        const nc = renew(jar, curCsrf);
        if (nc) { curCsrf = nc; renewed = true; retries++; continue; }
      }
      if (err === 'session' && !renewed) {
        const l = login(jar);
        if (l) { curCsrf = l.csrf; renewed = true; retries++; continue; }
      }
      workErr.add(1);
      bizFail.add(true);
      return { ok: false, csrf: curCsrf };
    }
    if (res.status >= 500) {
      workErr.add(1);
      bizFail.add(true);
      return { ok: false, csrf: curCsrf };
    }
    if (res.status >= 400) {
      workErr.add(1);
      bizFail.add(true);
      return { ok: false, csrf: curCsrf };
    }
    // success
    let body = null;
    try { body = res.json(); } catch (e) {}
    if (body && body.csrf) curCsrf = body.csrf;
    workOk.add(1);
    bizFail.add(false);
    return { ok: true, csrf: curCsrf };
  }
  workErr.add(1);
  bizFail.add(true);
  return { ok: false, csrf: curCsrf };
}

export default function () {
  const jar = http.cookieJar();
  const sess = login(jar);
  if (!sess) {
    bizFail.add(true);
    return;
  }
  let csrf = sess.csrf;

  // warmup: a couple of work calls
  for (let i = 0; i < 2; i++) {
    const r = doWork(jar, csrf);
    csrf = r.csrf;
  }

  // scored phase: aim for ~8 ops/s over ~30s per VU -> ~120 ops per VU
  // 2 VUs * 2 iterations = 4 iterations; each iteration ~30s of work
  const targetOps = 120;
  const start = Date.now();
  const durationMs = 30000;
  let done = 0;
  while (done < targetOps && Date.now() - start < durationMs) {
    const r = doWork(jar, csrf);
    csrf = r.csrf;
    done++;
    // pace to ~8/s per VU (2 VUs -> 16/s total, but target is 8/s aggregate)
    // pace per VU at 4/s
    const elapsed = Date.now() - start;
    const expected = (done / 4) * 1000;
    if (elapsed < expected) {
      const wait = (expected - elapsed) / 1000;
      try { require('k6').sleep(wait); } catch (e) {}
    }
  }
}
