import http from 'k6/http';
import { check } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const workStarts = new Counter('work_starts');
const workOk = new Counter('work_ok');
const workScheduled = new Counter('work_scheduled');
const workUnexpected = new Counter('work_unexpected');
const workDropped = new Counter('work_dropped');
const businessFailure = new Rate('business_failure');
const workLatency = new Trend('work_latency');

export const options = {
  scenarios: {
    work: {
      executor: 'constant-arrival-rate',
      rate: 8,
      timeUnit: '1s',
      duration: '40s',
      preAllocatedVUs: 16,
      maxVUs: 32,
      startTime: '0s',
      gracefulStop: '5s',
    },
  },
  thresholds: {
    work_unexpected: ['count<=1'],
    work_dropped: ['count<=1'],
  },
  discardResponseBodies: false,
  noConnectionReuse: false,
};

function parseCsrf(html) {
  // input[name=csrf] with mixed attribute variants
  const re = /<input\b[^>]*\bname\s*=\s*["']?csrf["']?[^>]*>/i;
  const m = html.match(re);
  if (!m) return null;
  const tag = m[0];
  const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
  return vm ? vm[1] : null;
}

function getCookie(jar, name) {
  const cookies = jar.cookiesForURL(BASE);
  const arr = cookies[name];
  return arr && arr.length ? arr[0] : null;
}

function login(user) {
  const jar = http.cookieJar();
  jar.clear(BASE);
  const formRes = http.get(`${BASE}/v2/login-form`, { redirects: 0 });
  if (formRes.status !== 200) return null;
  const csrf = parseCsrf(formRes.body);
  if (!csrf) return null;
  const loginRes = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username: user, password: 'bench', csrf }),
    { headers: { 'Content-Type': 'application/json' }, redirects: 0 }
  );
  let body = null;
  try { body = loginRes.json(); } catch (e) { body = null; }
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'] || loginRes.headers['location'];
    if (loc) {
      const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { redirects: 0 });
      try { body = follow.json(); } catch (e) { body = null; }
    }
  }
  if (!body || !body.csrf) return null;
  return { csrf: body.csrf, user: body.user || user };
}

function renew(session) {
  const res = http.post(
    `${BASE}/v2/session/renew`,
    '{}',
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': session.csrf,
      },
      redirects: 0,
    }
  );
  if (res.status === 200) {
    try {
      const b = res.json();
      if (b && b.csrf) session.csrf = b.csrf;
    } catch (e) {}
    return true;
  }
  return false;
}

function doWork(session) {
  let attempts = 0;
  let scheduledRetries = 0;
  while (attempts < 2) {
    attempts++;
    const res = http.post(
      `${BASE}/v2/work`,
      '{}',
      {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': session.csrf,
        },
        redirects: 0,
        tags: { name: 'work' },
      }
    );
    workStarts.add(1);
    workLatency.add(res.timings.duration);

    if (res.status === 429) {
      workScheduled.add(1);
      businessFailure.add(false);
      const ra = res.headers['Retry-After'] || res.headers['retry-after'];
      const wait = ra ? parseFloat(ra) * 1000 : 1000;
      if (scheduledRetries < 4) {
        scheduledRetries++;
        // sleep handled by arrival-rate pacing; do a short bounded wait
        const start = Date.now();
        while (Date.now() - start < Math.min(wait, 1000)) { /* busy wait bounded */ }
        continue;
      }
      workDropped.add(1);
      return;
    }

    if (res.status === 401) {
      let err = null;
      try { err = res.json().error; } catch (e) {}
      if (err === 'expired') {
        businessFailure.add(false);
        if (renew(session)) continue;
        workUnexpected.add(1);
        businessFailure.add(true);
        return;
      }
      if (err === 'session') {
        businessFailure.add(false);
        const fresh = login(session.user);
        if (fresh) { session.csrf = fresh.csrf; continue; }
        workUnexpected.add(1);
        businessFailure.add(true);
        return;
      }
      // denied or other
      workUnexpected.add(1);
      businessFailure.add(true);
      return;
    }

    if (res.status >= 400) {
      workUnexpected.add(1);
      businessFailure.add(true);
      return;
    }

    let ok = false;
    try {
      const b = res.json();
      ok = b && b.ok === true;
    } catch (e) {}
    if (ok) {
      workOk.add(1);
      businessFailure.add(false);
      // capture fresh csrf if present
      try {
        const b = res.json();
        if (b && b.csrf) session.csrf = b.csrf;
      } catch (e) {}
      return;
    }
    workUnexpected.add(1);
    businessFailure.add(true);
    return;
  }
  workDropped.add(1);
}

export default function () {
  const user = `bench-${((__VU - 1) % 16) + 1}`;
  const session = login(user);
  if (!session) {
    workDropped.add(1);
    return;
  }
  doWork(session);
}
