  const vm = tag.match(/value\s*=\s*["']([^"']*)["']/i);
  return vm ? vm[1] : null;
}

function getCookie(jar, name) {
  const cookies = jar.cookiesForURL(BASE);
  const arr = cookies[name];
  return arr && arr.length ? arr[0] : null;
}

function login() {
  const jar = http.cookieJar();
  // fresh login
  const formRes = http.get(`${BASE}/v2/login-form`, { tags: { name: 'login-form' } });
  const csrf = parseCsrf(formRes.body || '');
  if (!csrf) return null;
  const user = `bench-${1 + (__VU % 16)}`;
  const loginRes = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username: user, password: 'bench', csrf }),
    {
      headers: { 'Content-Type': 'application/json' },
      redirects: 0,
      tags: { name: 'login' },
    }
  );
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'];
    if (loc) {
      const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, {
        redirects: 0,
        tags: { name: 'login-redirect' },
      });
      if (follow.status >= 400) return null;
    }
  } else if (loginRes.status >= 400) {
    return null;
  }
  let body = null;
  try { body = JSON.parse(loginRes.body); } catch (e) { body = null; }
  const token = (body && body.csrf) || csrf;
  return { csrf: token, user };
}

function renew(session) {
  const res = http.post(
    `${BASE}/v2/session/renew`,
    JSON.stringify({}),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': session.csrf,
      },
      tags: { name: 'renew' },
    }
  );
  if (res.status >= 400) return false;
  let body = null;
  try { body = JSON.parse(res.body); } catch (e) { body = null; }
  if (body && body.csrf) session.csrf = body.csrf;
  return true;
}

function doWork(session) {
  let attempts = 0;
  let scheduledRetries = 0;
  while (attempts < 2) {
    attempts++;
    const res = http.post(
      `${BASE}/v2/work`,
      JSON.stringify({}),
      {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': session.csrf,
        },
        tags: { name: 'work' },
      }
    );
    workStarts.add(1);
    workLatency.add(res.timings.duration);

    if (res.status === 429) {
      workScheduled.add(1);
      businessFailure.add(false);
      const ra = res.headers['Retry-After'];
      const wait = ra ? parseFloat(ra) : 1;
      if (scheduledRetries < 4) {
        scheduledRetries++;
        sleep(wait);
        continue;
      }
      workDropped.add(1);
      return;
    }

    if (res.status === 401) {
      let err = null;
      try { err = JSON.parse(res.body).error; } catch (e) {}
      if (err === 'expired') {
        businessFailure.add(false);
        if (renew(session)) {
          continue;
        }
        workDropped.add(1);
        return;
      }
      // denied or session -> fail
      workUnexpected.add(1);
      businessFailure.add(true);
      return;
    }

    if (res.status >= 400) {
      workUnexpected.add(1);
      businessFailure.add(true);
      return;
    }

    let body = null;
    try { body = JSON.parse(res.body); } catch (e) {}
    if (body && body.csrf) session.csrf = body.csrf;
    if (body && body.ok === true) {
      workOk.add(1);
      businessFailure.add(false);
    } else {
      workUnexpected.add(1);
      businessFailure.add(true);
    }
    return;
  }
  workDropped.add(1);
}

export default function () {
  const session = login();
  if (!session) {
    workDropped.add(1);
    return;
  }
  doWork(session);
}
