const business = new Counter('business_responses');
const browseLatency = new Trend('browse_latency');
const checkoutLatency = new Trend('checkout_latency');
const browseOk = new Rate('browse_ok');
const checkoutOk = new Rate('checkout_ok');

const USERS = ['bench-1','bench-2','bench-3','bench-4','bench-5','bench-6','bench-7','bench-8','bench-9','bench-10','bench-11','bench-12','bench-13','bench-14','bench-15','bench-16'];

export const options = {
