  discardResponseBodies: false,
  noConnectionReuse: false,
  thresholds: {
    'browse_ok': ['rate>0.9'],
    'checkout_ok': ['rate>0.9'],
  },
};

function parseCsrf(html) {
  if (!html) return null;
  const re = /<input[^>]*name=["']?csrf["']?[^>]*value=["']([^"']+)["']/i;
  const m = html.match(re);
  if (m) return m[1];
  const re2 = /<input[^>]*value=["']([^"']+)["'][^>]*name=["']?csrf["']?/i;
  const m2 = html.match(re2);
  return m2 ? m2[1] : null;
}

function parseChallengeForm(html) {
  if (!html) return null;
  const actionM = html.match(/<form[^>]*action=["']([^"']+)["']/i);
  const inputM = html.match(/<input[^>]*name=["']?challenge["']?[^>]*value=["']([^"']*)["']/i);
  if (!actionM) return null;
  return { action: actionM[1], challenge: inputM ? inputM[1] : '' };
}

function getCookie(jar, name) {
  const cookies = jar.cookiesForURL(BASE);
  return cookies[name] ? cookies[name][0] : null;
}

function login(jar) {
  const user = USERS[Math.floor(Math.random() * USERS.length)];
  const formRes = http.get(`${BASE}/v2/login-form`, { jar, redirects: 0 });
  if (formRes.status >= 400) return null;
  const csrf = parseCsrf(formRes.body);
  if (!csrf) return null;
  const loginRes = http.post(`${BASE}/v2/login`, JSON.stringify({ username: user, password: 'bench', csrf }), {
    jar,
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
  });
  let body = loginRes.body;
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'];
    if (loc) {
      const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar, redirects: 0 });
      body = follow.body;
    }
  }
  let token = null;
  try {
    const j = JSON.parse(body);
    token = j.csrf;
  } catch (e) {
    token = parseCsrf(body);
  }
  return token;
}

function renew(jar, csrf) {
  const r = http.post(`${BASE}/v2/session/renew`, JSON.stringify({}), {
    jar,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  if (r.status >= 400) return null;
  try {
    const j = JSON.parse(r.body);
    return j.csrf || csrf;
  } catch (e) {
    return csrf;
  }
}

function recoverCart(jar, csrf, cartId) {
  const r = http.post(`${BASE}/v2/carts/${cartId}/recover`, JSON.stringify({}), {
    jar,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  if (r.status >= 400) return null;
  try {
    const j = JSON.parse(r.body);
    return j.csrf || csrf;
  } catch (e) {
    return csrf;
  }
}

function isExpired(res) {
  if (res.status !== 401) return false;
  try {
    const j = JSON.parse(res.body);
    return j.error === 'expired';
  } catch (e) {
    return false;
  }
}

function isDenied(res) {
  if (res.status !== 401) return false;
  try {
    const j = JSON.parse(res.body);
    return j.error === 'denied';
  } catch (e) {
    return false;
  }
}

function isSessionRevoked(res) {
  if (res.status !== 401) return false;
  try {
    const j = JSON.parse(res.body);
    return j.error === 'session';
  } catch (e) {
    return false;
  }
}

function doWork(jar, csrf, path) {
  let attempts = 0;
  let token = csrf;
  while (attempts < 5) {
    const res = http.post(`${BASE}${path}`, JSON.stringify({}), {
      jar,
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': token },
      redirects: 0,
    });
    if (res.status === 429) {
      const ra = parseFloat(res.headers['Retry-After'] || '1');
      sleep(Math.min(ra, 1));
      attempts++;
      continue;
    }
    if (isExpired(res)) {
      const nt = renew(jar, token);
      if (!nt) return { ok: false, res };
      token = nt;
      attempts++;
      continue;
    }
    if (res.status >= 400) {
      return { ok: false, res, token };
    }
    let newToken = token;
    try {
      const j = JSON.parse(res.body);
      if (j.csrf) newToken = j.csrf;
    } catch (e) {}
    return { ok: true, res, token: newToken };
  }
  return { ok: false, res: null, token };
}

function getCatalog(jar) {
  const r = http.get(`${BASE}/v2/catalog`, { jar, redirects: 0 });
  if (r.status >= 400) return null;
  try {
    const j = JSON.parse(r.body);
    return j.data && j.data.products ? j.data.products : null;
  } catch (e) {
    return null;
  }
}

function getCatalogPage(jar) {
  const r = http.get(`${BASE}/v2/catalog/page`, { jar, redirects: 0 });
  if (r.status >= 400) return null;
  try {
    return JSON.parse(r.body);
  } catch (e) {
    return null;
  }
}

function pickVariant(products) {
  for (const p of products) {
    if (p.variants) {
      for (const v of p.variants) {
        if (v.in_stock) return { product_id: p.id, variant_id: v.id };
      }
    }
  }
  return null;
}

function solveChallenge(jar, csrf) {
  const formRes = http.get(`${BASE}/v2/challenge-form`, { jar, redirects: 0 });
  if (formRes.status >= 400) return null;
  const cf = parseChallengeForm(formRes.body);
  if (!cf) return null;
  const action = cf.action.startsWith('http') ? cf.action : `${BASE}${cf.action}`;
  const postRes = http.post(action, JSON.stringify({ challenge: cf.challenge }), {
    jar,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  if (postRes.status === 302) {
    const loc = postRes.headers['Location'];
    if (loc) {
      const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar, redirects: 0 });
      try {
        const j = JSON.parse(follow.body);
        return { grant_id: j.grant_id, csrf: j.csrf || csrf };
      } catch (e) {
        return null;
      }
    }
  }
  return null;
}

function createCart(jar, csrf, productId, variantId, grantId) {
  const payload = { product_id: productId, variant_id: variantId };
  if (grantId) payload.grant_id = grantId;
  const r = http.post(`${BASE}/v2/carts`, JSON.stringify(payload), {
    jar,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  if (r.status === 401 && isExpired(r)) {
    const nt = renew(jar, csrf);
    if (!nt) return null;
    return createCart(jar, nt, productId, variantId, grantId);
  }
  if (r.status >= 400) return null;
  try {
    const j = JSON.parse(r.body);
    return { id: j.id, csrf: j.csrf || csrf, etag: r.headers['Etag'] };
  } catch (e) {
    return null;
  }
}

function patchCart(jar, csrf, cartId, etag, qty) {
  const r = http.patch(`${BASE}/v2/carts/${cartId}`, JSON.stringify({ quantity: qty }), {
    jar,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf, 'If-Match': etag || '' },
    redirects: 0,
  });
  if (r.status === 412) {
    const g = http.get(`${BASE}/v2/carts/${cartId}`, { jar, redirects: 0 });
    const newEtag = g.headers['Etag'];
    const r2 = http.patch(`${BASE}/v2/carts/${cartId}`, JSON.stringify({ quantity: qty }), {
      jar,
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf, 'If-Match': newEtag || '' },
      redirects: 0,
    });
    if (r2.status >= 400) return null;
    try {
      const j = JSON.parse(r2.body);
      return { csrf: j.csrf || csrf, etag: r2.headers['Etag'] };
    } catch (e) {
      return { csrf, etag: r2.headers['Etag'] };
    }
  }
  if (r.status === 401 && isExpired(r)) {
    const nt = renew(jar, csrf);
    if (!nt) return null;
    const rec = recoverCart(jar, nt, cartId);
    if (!rec) return null;
    return patchCart(jar, rec, cartId, etag, qty);
  }
  if (r.status >= 400) return null;
  try {
    const j = JSON.parse(r.body);
    return { csrf: j.csrf || csrf, etag: r.headers['Etag'] };
  } catch (e) {
    return { csrf, etag: r.headers['Etag'] };
  }
}

function reserve(jar, csrf, cartId) {
  const r = http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    jar,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  if (r.status === 401 && isExpired(r)) {
    const nt = renew(jar, csrf);
    if (!nt) return null;
    return reserve(jar, nt, cartId);
  }
  if (r.status >= 400) return null;
  let j;
  try { j = JSON.parse(r.body); } catch (e) { return null; }
  const statusUrl = j.status_url;
  let token = j.csrf || csrf;
  if (!statusUrl) return null;
  for (let i = 0; i < 5; i++) {
    sleep(0.06);
    const s = http.get(statusUrl.startsWith('http') ? statusUrl : `${BASE}${statusUrl}`, { jar, redirects: 0 });
    if (s.status >= 400) return null;
    let sj;
    try { sj = JSON.parse(s.body); } catch (e) { return null; }
    if (sj.csrf) token = sj.csrf;
    if (sj.status === 'ready') return { reservation_id: sj.reservation_id, csrf: token };
    if (sj.status === 'failed') return null;
  }
  return null;
}

function placeOrder(jar, csrf, cartId, reservationId, idemKey) {
  const payload = { cart_id: cartId };
  if (reservationId) payload.reservation_id = reservationId;
  const r = http.post(`${BASE}/v2/orders`, JSON.stringify(payload), {
    jar,
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'Idempotency-Key': idemKey,
    },
    redirects: 0,
  });
  if (r.status === 401 && isExpired(r)) {
    const nt = renew(jar, csrf);
    if (!nt) return { ok: false, res: r };
    const rec = recoverCart(jar, nt, cartId);
    if (!rec) return { ok: false, res: r };
    return placeOrder(jar, rec, cartId, reservationId, idemKey);
  }
  if (r.status >= 400) return { ok: false, res: r };
  try {
    const j = JSON.parse(r.body);
    if (j.accepted === true) return { ok: true, res: r, csrf: j.csrf || csrf };
    return { ok: false, res: r };
  } catch (e) {
    return { ok: false, res: r };
  }
}

export function browseFlow() {
  const jar = http.cookieJar();
  const csrf = login(jar);
  if (!csrf) {
    browseErrors.add(1);
    return;
  }
  const t0 = Date.now();
  const r = doWork(jar, csrf, '/v2/browse');
  const dt = Date.now() - t0;
  if (r.ok) {
    browseStarts.add(1);
    browseLatency.add(dt);
    browseOk.add(1);
    business.add(1);
  } else {
    browseErrors.add(1);
    browseOk.add(0);
    if (r.res && r.res.status >= 500) unexpected.add(1);
    if (r.res) business.add(1);
  }
}

export function checkoutFlow() {
  const jar = http.cookieJar();
  let csrf = login(jar);
  if (!csrf) {
    checkoutErrors.add(1);
    return;
  }
  const products = getCatalog(jar);
  let picked = products ? pickVariant(products) : null;
  if (!picked) {
    const page = getCatalogPage(jar);
    if (page && page.product) {
      const p = page.product;
      if (p.variants) {
        for (const v of p.variants) {
          if (v.in_stock) { picked = { product_id: p.id, variant_id: v.id }; break; }
        }
      }
    }
  }
  if (!picked) {
    checkoutErrors.add(1);
    return;
  }
  let grantId = null;
  const ch = solveChallenge(jar, csrf);
  if (ch) {
    grantId = ch.grant_id;
    csrf = ch.csrf;
  }
  const cart = createCart(jar, csrf, picked.product_id, picked.variant_id, grantId);
  if (!cart) {
    checkoutErrors.add(1);
    return;
  }
  csrf = cart.csrf;
  const patched = patchCart(jar, csrf, cart.id, cart.etag, 1);
  if (!patched) {
    checkoutErrors.add(1);
    return;
  }
  csrf = patched.csrf;
  const resv = reserve(jar, csrf, cart.id);
  if (!resv) {
    checkoutErrors.add(1);
    return;
  }
  csrf = resv.csrf;
  const idemKey = `idem-${cart.id}-${Date.now()}`;
  const t0 = Date.now();
  const order = placeOrder(jar, csrf, cart.id, resv.reservation_id, idemKey);
  const dt = Date.now() - t0;
  if (order.ok) {
    checkoutStarts.add(1);
    checkoutLatency.add(dt);
    checkoutOk.add(1);
    business.add(1);
  } else {
    checkoutErrors.add(1);
    checkoutOk.add(0);
    if (order.res && order.res.status >= 500) unexpected.add(1);
    if (order.res) business.add(1);
  }
}
